function updateHeaderCounts()
{
  const cartCount =
  document.getElementById(
    "cartCount"
  );

  const favCount =
  document.getElementById(
    "favCount"
  );

  if (
    cartCount
  )
  {
    cartCount.textContent =
    String(
      state.cart.reduce(
        (
          total,
          line
        ) =>
        total +
        Math.max(
          1,
          asNumber(
            line.qty,
            1
          )
        ),
        0
      )
    );
  }

  if (
    favCount
  )
  {
    favCount.textContent =
    String(
      state.favorites.length
    );
  }
}

function toast(
  message,
  type = "success",
  timeout = 3400
)
{
  const stack =
  document.getElementById(
    "toastStack"
  );

  if (
    !stack
  )
  {
    return;
  }

  const node =
  document.createElement(
    "div"
  );

  node.className =
  "toast " +
  type;

  node.textContent =
  String(
    message
  );

  stack.appendChild(
    node
  );

  window.setTimeout(
    () =>
    {
      node.remove();
    },
    timeout
  );
}

function setAppLoading(
  label =
  t(
    "common.loading"
  )
)
{
  const app =
  document.getElementById(
    "app"
  );

  if (
    !app
  )
  {
    return;
  }

  app.innerHTML =
  `
    <div class="loading-state">
      <div class="spinner"></div>
      <p>
        ${escapeHtml(label)}
      </p>
    </div>
  `;
}

function openModal(
  title,
  bodyHtml
)
{
  const modal =
  document.getElementById(
    "modal"
  );

  const modalTitle =
  document.getElementById(
    "modalTitle"
  );

  const modalBody =
  document.getElementById(
    "modalBody"
  );

  if (
    !modal ||
    !modalTitle ||
    !modalBody
  )
  {
    return;
  }

  modalTitle.textContent =
  String(
    title ||
    "AromaLParfum"
  );

  modalBody.innerHTML =
  bodyHtml ||
  "";

  modal.classList.add(
    "open"
  );

  modal.setAttribute(
    "aria-hidden",
    "false"
  );

  document.body.classList.add(
    "no-scroll"
  );
}

