  "familia",
  "duracion",
  "proyeccion",
  "recomendacion_uso",
  "estaciones",
  "ocasiones",
  "destacado",
  "nuevo",
  "vendido",
  "tipo_producto",
  "tipo_producto_slug",
  "subcategoria",
  "imagen_url",
  "created_by_ai",
  "descripcion_en",
  "salida_en",
  "corazon_en",
