async function loadAllData()
{
  state.loading =
  true;

  state.lastError =
  null;

  setAppLoading(
    t(
      "common.loading"
    )
  );

  try
  {
    await Promise.all(
      [
        loadProducts(),
        loadSiteSettings(),
        loadPopularity(),
        loadCollections(),
        loadGameConfigs(),
        loadDailyLeaderboard(),
        loadProductTypes(),
        loadComboTemplates(),
        loadComboProducts(),
        loadDecantSizes(),
        loadGiftOptions(),
      ]
    );

    await loadMainProductImages();

    await Promise.all(
      [
        loadSiteCoverUrls(),
        loadSeasonalVideoUrl(),
      ]
    );

    state.loading =
    false;

    applyLanguageToChrome();

    renderCurrentRoute();
  }
  catch (
    error
  )
  {
    state.loading =
    false;

    state.lastError =
    error;

    console.error(
      "Error inicializando AromaLParfum:",
      error
    );

    const app =
    document.getElementById(
      "app"
    );

    if (
      app
    )
    {
      app.innerHTML =
      `
        <section class="section">
          <div class="container">
            <div class="empty-state">
              <h3>
                No se pudo cargar AromaLParfum
              </h3>
              <p>
                ${escapeHtml(error?.message || "Error desconocido")}
              </p>
              <button
                class="btn"
                type="button"
                data-action="reload-data">
                ${escapeHtml(t("common.retry"))}
              </button>
            </div>
          </div>
        </section>
      `;
    }
  }
}

function setRoute(
  route,
  payload = {}
)
{
  state.route =
  route;

  state.routePayload =
  payload
  ||
  {};

  closeMenu();

  closeCart();

  closeModal();

  renderCurrentRoute();

  window.scrollTo(
    {
      top:
      0,

      behavior:
      "smooth",
    }
  );
}

function renderCurrentRoute()
{
  const app =
  document.getElementById(
    "app"
  );

  if (
    !app
  )
  {
    return;
  }

  if (
    state.loading
  )
  {
    setAppLoading();

    return;
  }

  switch (
    state.route
  )
  {
    case "catalog":
    {
      app.innerHTML =
      renderCatalogPage();

      break;
    }

    case "best":
    {
      app.innerHTML =
      renderBestSellersPage();

      break;
    }

    case "collections":
    {
      app.innerHTML =
      renderCollectionsPage();

      break;
    }

    case "collection":
    {
      app.innerHTML =
      renderCollectionDetailPage(
        state.routePayload.slug
      );

      break;
    }

    case "decants":
    {
      app.innerHTML =
      renderDecantBuilderPage();

      break;
    }

    case "gifts":
    {
      app.innerHTML =
      renderGiftBuilderPage();

      break;
    }

    case "games":
    {
      app.innerHTML =
      renderGamesHubPage();

      break;
    }

    case "game":
    {
      app.innerHTML =
      renderGamePage();

      afterRenderGame();

      break;
    }

    case "advisor":
    {
      app.innerHTML =
      renderAdvisorPage();

      break;
    }

    case "favorites":
    {
      app.innerHTML =
      renderFavoritesPage();

      break;
    }

    case "product":
    {
      app.innerHTML =
      renderProductDetailPage(
        state.routePayload.id
      );

      ensureProductGallery(
        state.routePayload.id
      );

      break;
    }

    case "personal-care":
    {
      app.innerHTML =
      renderPersonalCarePage();

      break;
    }

    case "gift-sets":
    {
      app.innerHTML =
      renderGiftSetsPage();

      break;
    }

    case "discovery":
    {
      app.innerHTML =
      renderDiscoveryPage();

      break;
    }

    case "about":
    {
      app.innerHTML =
      renderAboutPage();

      break;
    }

    case "contact":
    {
      app.innerHTML =
      renderContactPage();

      break;
    }

    case "admin":
    {
      renderAdminRoute();

      break;
    }

    case "home":
    default:
    {
      app.innerHTML =
      renderHomePage();

      break;
    }
  }

  applyLanguageToChrome();

  updateHeaderCounts();

  if (
    state.route === "games"
  )
  {
    setTimeout(
      () =>
      activateGameAds(),
      0
    );
  }
}

