function renderSocialButton(
  network,
  url
)
{
  const safeUrl =
  String(
    url ||
    ""
  ).trim();

  if (
    safeUrl === ""
  )
  {
    return "";
  }

  const iconMap =
  {
    instagram:
    `
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <rect x="3.5" y="3.5" width="17" height="17" rx="5"></rect>
        <circle cx="12" cy="12" r="4"></circle>
        <circle cx="17.3" cy="6.8" r=".8" fill="currentColor" stroke="none"></circle>
      </svg>
    `,

    tiktok:
    `
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <path d="M14.2 4.2v10.1a4.1 4.1 0 1 1-3.4-4"></path>
        <path d="M14.2 4.2c.8 2.5 2.3 3.9 4.8 4.4"></path>
      </svg>
    `,

    facebook:
    `
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <path d="M13.8 21v-8h2.8l.5-3h-3.3V8.1c0-.9.3-1.6 1.7-1.6h1.8V3.8c-.4-.1-1.4-.2-2.6-.2-2.6 0-4.3 1.5-4.3 4.4v2H7.6v3h2.8v8"></path>
      </svg>
    `,

    youtube:
    `
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <rect x="3" y="6" width="18" height="12" rx="4"></rect>
        <path d="m10 9 5 3-5 3z" fill="currentColor" stroke="none"></path>
      </svg>
    `,
  };

  const icon =
  iconMap[
    network
  ]
  ||
  escapeHtml(
    network
    .slice(
      0,
      2
    )
    .toUpperCase()
  );

  return `
    <a
      class="social-btn"
      href="${escapeAttribute(safeUrl)}"
      target="_blank"
      rel="noopener noreferrer"
      aria-label="${escapeAttribute(network)}">
      ${icon}
    </a>
  `;
}

function getFeaturedProducts()
{
  const explicit =
  state.products
  .filter(
    product =>
    product.destacado === true &&
    product.stock > 0
  );

  if (
    explicit.length
  )
  {
    return explicit;
  }

  return state.products
  .filter(
    product =>
    product.stock > 0
  )
  .slice(
    0,
    10
  );
}

function getNewProducts()
{
  return state.products
  .filter(
    product =>
    isNewProduct(
      product
    )
  )
  .sort(
    (
      a,
      b
    ) =>
    {
      const dateA =
      new Date(
        a.created_at
        ||
        0
      )
      .getTime();

      const dateB =
      new Date(
        b.created_at
        ||
        0
      )
      .getTime();

      return dateB - dateA;
    }
  );
}

function getBestSellerProducts()
{
  return [
    ...state.products,
  ]
  .sort(
    (
      a,
      b
    ) =>
    {
      const popularityDiff =
      getPopularity(
        b.id
      )
      -
      getPopularity(
        a.id
      );

      if (
        popularityDiff !== 0
      )
      {
        return popularityDiff;
      }

      return (
        Number(
          b.destacado
        )
        -
        Number(
          a.destacado
        )
      );
    }
  );
}

function getHeroCollections()
{
  const collections =
  state.collections
  .filter(
    collection =>
    collection.activo !== false
  );

  return collections.length
  ?
  collections
  :
  CONFIG.collectionFallbacks;
}

function getProductsForCollection(
  collection
)
{
  if (
    !collection
  )
  {
    return [];
  }

  const station =
  normalizeText(
    collection.estacion
  );

  const occasion =
  normalizeText(
    collection.ocasion
  );

  return state.products.filter(
    product =>
    {
      if (
        collection.tipo === "seasonal" &&
        station
      )
      {
        return arrayFromDb(
          product.estaciones
        )
        .some(
          value =>
          normalizeText(
            value
          ) ===
          station
        );
      }

      if (
        collection.tipo === "occasion" &&
        occasion
      )
      {
        return arrayFromDb(
          product.ocasiones
        )
        .some(
          value =>
          normalizeText(
            value
          ) ===
          occasion
        );
      }

      return false;
    }
  );
}

function getHeroProductForCollection(
  collection
)
{
  const matches =
  getProductsForCollection(
    collection
  );

  const imageMatch =
  matches.find(
    product =>
    Boolean(
      getProductMainImage(
        product
      )
    )
  );

  return (
    imageMatch
    ||
    matches[0]
    ||
    getFeaturedProducts().find(
      product =>
      Boolean(
        getProductMainImage(
          product
        )
      )
    )
    ||
    getFeaturedProducts()[0]
    ||
    state.products[0]
    ||
    null
  );
}

function renderHomePage()
{
  const heroCollections =
  getHeroCollections();

  const safeHeroIndex =
  clamp(
    state.heroCollectionIndex,
    0,
    Math.max(
      0,
      heroCollections.length - 1
    )
  );

  state.heroCollectionIndex =
  safeHeroIndex;

  const heroCollection =
  heroCollections[
    safeHeroIndex
  ];

  const heroProduct =
  getHeroProductForCollection(
    heroCollection
  );

  const featured =
  getFeaturedProducts()
  .slice(
    0,
    10
  );

  const newProducts =
  getNewProducts()
  .slice(
    0,
    10
  );

  const best =
  getBestSellerProducts()
  .filter(
    product =>
    getPopularity(
      product.id
    ) > 0
  )
  .slice(
    0,
    10
  );

  return `
    ${renderHero(heroCollection, heroProduct, heroCollections)}

    ${renderCategoryRail()}

    ${renderSeasonalVideo()}

    ${renderProductRowSection(
      t("featured.eyebrow"),
      t("featured.title"),
      featured,
      {
        route:
        "catalog",

        actionLabel:
        t("featured.viewall"),

        badge:
        "featured",
      }
    )}

    ${renderProductRowSection(
      t("new.eyebrow"),
      t("new.title"),
      newProducts,
      {
        route:
        "catalog",

        filter:
        "Nuevo",

        badge:
        "new",
      }
    )}

    ${best.length
      ?
      renderProductRowSection(
        t("best.eyebrow"),
        t("best.title"),
        best,
        {
          route:
          "best",

          badge:
          "best",

          description:
          t("best.description"),
        }
      )
      :
      ""
    }

    ${renderPromoBuilders()}

    ${renderAdvisorTeaser()}

    ${renderServiceStrip()}
  `;
}

function renderHero(
  collection,
  product,
  collections
)
{
  const customCover =
  getCollectionCoverUrl(
    collection?.slug || ""
  )
  ||
  getSiteCoverUrl(
    "hero"
  );

  const fallbackImage =
  product
  ?
  getProductMainImage(
    product
  )
  :
  "";

  const image =
  customCover
  ||
  fallbackImage;

  const hasCustomCover =
  Boolean(
    customCover
  );

  const coverPosition =
  coverPositionCss(
    getSiteCoverPosition(
      "hero"
    )
  );

  const collectionName =
  localizedCollectionName(
    collection
  )
  ||
  t(
    "hero.eyebrow"
  );

  const collectionDescription =
  localizedCollectionDescription(
    collection
  )
  ||
  t(
    "hero.description"
  );

  const heroStyle =
  hasCustomCover
  ?
  `style="--hero-cover-image:url(&quot;${escapeAttribute(customCover)}&quot;);--hero-cover-position:${escapeAttribute(coverPosition)};--hero-cover-position-mobile:${escapeAttribute(coverPosition)};"`
  :
  "";

  return `
    <section
      class="luxury-hero ${hasCustomCover ? "hero-cover-active" : ""}"
      ${heroStyle}>
      <div class="container">
        <div class="luxury-hero-grid">
          <div class="hero-copy">
            <p class="eyebrow">
              ${escapeHtml(collectionName)}
            </p>

            <h1>
              ${escapeHtml(t("hero.title"))}
            </h1>

            <p>
              ${escapeHtml(collectionDescription)}
            </p>

            <button
              class="btn"
              type="button"
              data-route="collection"
              data-collection-slug="${escapeAttribute(collection?.slug || "")}">
              ${escapeHtml(t("hero.cta"))}
              <span aria-hidden="true">→</span>
            </button>
          </div>

          ${hasCustomCover
            ?
            ""
            :
            `
              <div class="hero-visual">
                <div class="hero-product-stage">
                  ${image
                    ?
                    `
                      <img
                        src="${escapeAttribute(image)}"
                        alt="${escapeAttribute(product?.nombre || "Perfume")}">
                    `
                    :
                    `
                      <div class="hero-product-fallback">
                        ${escapeHtml(product?.nombre || "AromaLParfum")}
                      </div>
                    `
                  }
                </div>
              </div>

              <div class="hero-benefits">
                <div class="hero-benefit">
                  <span class="hero-benefit-icon">✦</span>
                  <span>${escapeHtml(t("hero.benefit1"))}</span>
                </div>

                <div class="hero-benefit">
                  <span class="hero-benefit-icon">◌</span>
                  <span>${escapeHtml(t("hero.benefit2"))}</span>
                </div>

                <div class="hero-benefit">
                  <span class="hero-benefit-icon">🎁</span>
                  <span>${escapeHtml(t("hero.benefit3"))}</span>
                </div>

                <div class="hero-benefit">
                  <span class="hero-benefit-icon">♡</span>
                  <span>${escapeHtml(t("hero.benefit4"))}</span>
                </div>
              </div>
            `
          }
        </div>
      </div>

      <div class="hero-collection-tabs">
        ${collections
          .map(
            (
              item,
              index
            ) =>
            `
              <button
                class="hero-collection-tab ${index === state.heroCollectionIndex ? "active" : ""}"
                type="button"
                data-action="select-hero-collection"
                data-index="${index}">
                ${(item.emoji || "") + " " + escapeHtml(localizedCollectionName(item))}
              </button>
            `
          )
          .join("")
        }
      </div>
    </section>
  `;
}

