function renderSeasonalVideo()
{
  const video =
  getSiteSettingObject(
    "seasonal_video"
  );

  const source =
  getSeasonalVideoUrl();

  if (
    video.enabled !== true ||
    !source
  )
  {
    return "";
  }

  const title =
  (
    state.language === "en"
    ?
    video.title_en
    :
    video.title_es
  )
  ||
  (
    state.language === "en"
    ?
    "Seasonal Fragrances"
    :
    "Perfumes de temporada"
  );

  const autoplay =
  video.autoplay === true;

  const muted =
  autoplay
  ?
  true
  :
  video.muted === true;

  const loop =
  video.loop !== false;

  return `
    <section class="seasonal-video">
      <div class="container">
        <div class="seasonal-video-grid">
          <div class="seasonal-video-copy">
            <p class="eyebrow">
              ${escapeHtml(t("hero.eyebrow"))}
            </p>

            <h2>
              ${escapeHtml(title)}
            </h2>

            <p>
              ${escapeHtml(t("hero.description"))}
            </p>
          </div>

          <div class="seasonal-video-media">
            <video
              controls
              playsinline
              preload="metadata"
              ${autoplay ? "autoplay" : ""}
              ${muted ? "muted" : ""}
              ${loop ? "loop" : ""}
              src="${escapeAttribute(source)}">
            </video>
          </div>
        </div>
      </div>
    </section>
  `;
}

function renderProductRowSection(
  eyebrow,
  title,
  products,
  options = {}
)
{
  if (
    !products ||
    products.length === 0
  )
  {
    return "";
  }

  return `
    <section class="section">
      <div class="container">
        <div class="section-title-row">
          <div>
            <p class="eyebrow">
              ${escapeHtml(eyebrow)}
            </p>

            <h2 class="section-title">
              ${escapeHtml(title)}
            </h2>

            ${options.description
              ?
              `
                <p class="section-subtitle">
                  ${escapeHtml(options.description)}
                </p>
              `
              :
              ""
            }
          </div>

          ${options.route
            ?
            `
              <button
                class="text-link"
                type="button"
                data-route="${escapeAttribute(options.route)}"
                ${options.filter ? `data-filter="${escapeAttribute(options.filter)}"` : ""}>
                ${escapeHtml(options.actionLabel || t("featured.viewall"))}
                <span aria-hidden="true">→</span>
              </button>
            `
            :
            ""
          }
        </div>

        <div class="product-row-scroller">
          ${products
            .map(
              product =>
              renderProductCard(
                product,
                {
                  badge:
                  options.badge,
                }
              )
            )
            .join("")
          }
        </div>
      </div>
    </section>
  `;
}

function renderProductCard(
  product,
  options = {}
)
{
  const image =
  getProductMainImage(
    product
  );

  const badges =
  [];

  if (
    isNewProduct(
      product
    )
  )
  {
    badges.push(
      {
        type:
        "new",

        text:
        t(
          "product.new"
        ),
      }
    );
  }

  if (
    product.destacado
  )
  {
    badges.push(
      {
        type:
        "featured",

        text:
        t(
          "product.featured"
        ),
      }
    );
  }

  if (
    options.badge === "best" ||
    getPopularity(
      product.id
    ) > 0 &&
    getBestSellerProducts()
    .slice(
      0,
      5
    )
    .some(
      item =>
      item.id === product.id
    )
  )
  {
    badges.push(
      {
        type:
        "best",

        text:
        t(
          "product.best"
        ),
      }
    );
  }

  const notes =
  [
    localizedField(
      product,
      "salida"
    ),

    localizedField(
      product,
      "corazon"
    ),
  ]
  .filter(
    Boolean
  )
  .join(
    " · "
  );

  return `
    <article class="product-card">
      <div class="product-media">
        <div class="product-badges">
          ${badges
            .slice(
              0,
              2
            )
            .map(
              badge =>
              `
                <span class="badge ${escapeAttribute(badge.type)}">
                  ${escapeHtml(badge.text)}
                </span>
              `
            )
            .join("")
          }
        </div>

        <button
          class="fav-mini ${isFavorite(product.id) ? "active" : ""}"
          type="button"
          aria-label="${escapeAttribute(t("nav.favorites"))}"
          data-action="toggle-favorite"
          data-product-id="${product.id}">
          ${isFavorite(product.id) ? "♥" : "♡"}
        </button>

        <button
          type="button"
          style="all:unset;cursor:pointer;width:100%;height:100%;display:block"
          data-route="product"
          data-product-id="${product.id}">
          ${image
            ?
            `
              <img
                src="${escapeAttribute(image)}"
                alt="${escapeAttribute(product.nombre)}"
                loading="lazy"
                decoding="async">
            `
            :
            `
              <div class="product-placeholder">
                ${escapeHtml(product.nombre)}
              </div>
            `
          }
        </button>
      </div>

      <div class="product-body">
        <div class="product-kicker">
          ${escapeHtml(product.marca || product.categoria)}
          ·
          ${escapeHtml(product.genero)}
        </div>

        <h3 class="product-title">
          ${escapeHtml(product.nombre)}
        </h3>

        <p class="product-notes">
          ${escapeHtml(notes || localizedField(product, "familia") || t("common.consult"))}
        </p>

        <div class="product-bottom">
          <span class="product-price">
            ${money(product.precio)}
          </span>

          <button
            class="add-circle"
            type="button"
            title="${escapeAttribute(t("product.add"))}"
            data-action="add-product"
            data-product-id="${product.id}"
            ${product.stock <= 0 ? "disabled" : ""}>
            +
          </button>
        </div>
      </div>
    </article>
  `;
}

