function getCatalogProducts()
{
  const filter =
  state.catalogFilter;

  const searchTerm =
  normalizeText(
    state.catalogSearch
  );

  let list =
  state.products.filter(
    product =>
    {
      if (
        filter === "Nuevo"
      )
      {
        if (
          !isNewProduct(
            product
          )
        )
        {
          return false;
        }
      }
      else if (
        filter === "Destacado"
      )
      {
        if (
          !product.destacado
        )
        {
          return false;
        }
      }
      else if (
        filter !== "Todos"
      )
      {
        const matches =
        [
          product.categoria,
          product.genero,
          product.tipo_producto_slug,
          product.tipo_producto,
        ]
        .some(
          value =>
          normalizeText(
            value
          ) ===
          normalizeText(
            filter
          )
        );

        if (
          !matches
        )
        {
          return false;
        }
      }

      if (
        searchTerm
      )
      {
        const haystack =
        normalizeText(
          [
            product.nombre,
            product.marca,
            product.categoria,
            product.genero,
            product.familia,
            product.salida,
            product.corazon,
            product.fondo,
          ]
          .join(
            " "
          )
        );

        if (
          !haystack.includes(
            searchTerm
          )
        )
        {
          return false;
        }
      }

      return true;
    }
  );

  switch (
    state.catalogSort
  )
  {
    case "low":
    {
      list.sort(
        (
          a,
          b
        ) =>
        a.precio -
        b.precio
      );

      break;
    }

    case "high":
    {
      list.sort(
        (
          a,
          b
        ) =>
        b.precio -
        a.precio
      );

      break;
    }

    case "name":
    {
      list.sort(
        (
          a,
          b
        ) =>
        a.nombre.localeCompare(
          b.nombre,
          currentLanguage()
        )
      );

      break;
    }

    case "stock":
    {
      list.sort(
        (
          a,
          b
        ) =>
        b.stock -
        a.stock
      );

      break;
    }

    default:
    {
      list.sort(
        (
          a,
          b
        ) =>
        {
          const featuredDiff =
          Number(
            b.destacado
          )
          -
          Number(
            a.destacado
          );

          if (
            featuredDiff !== 0
          )
          {
            return featuredDiff;
          }

          return (
            getPopularity(
              b.id
            )
            -
            getPopularity(
              a.id
            )
          );
        }
      );
    }
  }

  return list;
}

function renderCatalogPage()
{
  const list =
  getCatalogProducts();

  const pageSize =
  Math.max(
    1,
    asNumber(
      state.catalogPageSize,
      24
    )
  );

  const totalPages =
  Math.max(
    1,
    Math.ceil(
      list.length /
      pageSize
    )
  );

  state.catalogPage =
  Math.min(
    totalPages,
    Math.max(
      1,
      asNumber(
        state.catalogPage,
        1
      )
    )
  );

  const pageStart =
  (
    state.catalogPage -
    1
  )
  *
  pageSize;

  const pageItems =
  list.slice(
    pageStart,
    pageStart +
    pageSize
  );

  const chips =
  [
    "Todos",
    "Nuevo",
    "Destacado",
    "Hombre",
    "Mujer",
    "Unisex",
    "Árabe",
    "Argentina",
    "Nicho",
    "Diseñador",
  ];

  const visiblePages =
  [];

  if (
    totalPages <=
    7
  )
  {
    for (
      let page = 1;
      page <= totalPages;
      page += 1
    )
    {
      visiblePages.push(
        page
      );
    }
  }
  else
  {
    const candidates =
    new Set(
      [
        1,
        totalPages,
        state.catalogPage - 2,
        state.catalogPage - 1,
        state.catalogPage,
        state.catalogPage + 1,
        state.catalogPage + 2,
      ]
      .filter(
        page =>
        page >= 1 &&
        page <= totalPages
      )
    );

    visiblePages.push(
      ...Array.from(
        candidates
      )
      .sort(
        (
          a,
          b
        ) =>
        a - b
      )
    );
  }

  const pageButtons =
  [];

  let previousPage =
  null;

  for (
    const page of
    visiblePages
  )
  {
    if (
      previousPage !== null &&
      page -
      previousPage >
      1
    )
    {
      pageButtons.push(
        `
          <span
            class="catalog-page-info"
            style="width:auto;margin:0 2px">
            …
          </span>
        `
      );
    }

    pageButtons.push(
      `
        <button
          class="catalog-page-btn ${page === state.catalogPage ? "active" : ""}"
          type="button"
          data-action="catalog-page"
          data-page="${page}">
          ${page}
        </button>
      `
    );

    previousPage =
    page;
  }

  return `
    <section class="section">
      <div class="container">
        <div class="section-title-row">
          <div>
            <p class="eyebrow">
              ${escapeHtml(t("catalog.eyebrow"))}
            </p>

            <h1 class="section-title">
              ${escapeHtml(t("catalog.title"))}
            </h1>

            <p class="section-subtitle">
              ${formatInteger(list.length)}
              ${state.language === "en" ? "products" : "productos"}
              ${list.length
                ?
                ` · ${state.language === "en" ? "Page" : "Página"} ${state.catalogPage} ${state.language === "en" ? "of" : "de"} ${totalPages}`
                :
                ""
              }
            </p>
          </div>
        </div>

        <div class="chips">
          ${chips
            .map(
              chip =>
              `
                <button
                  class="chip ${state.catalogFilter === chip ? "active" : ""}"
                  type="button"
                  data-action="catalog-filter"
                  data-filter="${escapeAttribute(chip)}">
                  ${escapeHtml(
                    chip === "Todos"
                    ?
                    t("common.all")
                    :
                    chip === "Nuevo"
                    ?
                    t("product.new")
                    :
                    chip === "Destacado"
                    ?
                    t("product.featured")
                    :
                    chip
                  )}
                </button>
              `
            )
            .join("")
          }
        </div>

        <div class="catalog-toolbar">
          <input
            id="catalogSearch"
            class="search-input"
            type="search"
            value="${escapeAttribute(state.catalogSearch)}"
            placeholder="${escapeAttribute(t("catalog.search"))}">

          <select
            id="catalogSort"
            class="select-input">
            <option value="default" ${state.catalogSort === "default" ? "selected" : ""}>
              ${escapeHtml(t("catalog.sort.default"))}
            </option>

            <option value="low" ${state.catalogSort === "low" ? "selected" : ""}>
              ${escapeHtml(t("catalog.sort.low"))}
            </option>

            <option value="high" ${state.catalogSort === "high" ? "selected" : ""}>
              ${escapeHtml(t("catalog.sort.high"))}
            </option>

            <option value="name" ${state.catalogSort === "name" ? "selected" : ""}>
              ${escapeHtml(t("catalog.sort.name"))}
            </option>

            <option value="stock" ${state.catalogSort === "stock" ? "selected" : ""}>
              ${escapeHtml(t("catalog.sort.stock"))}
            </option>
          </select>

          <button
            class="btn outline"
            type="button"
            data-action="clear-catalog">
            ${escapeHtml(t("common.none"))}
          </button>
        </div>

        ${list.length
          ?
          `
            <div class="catalog-grid">
              ${pageItems
                .map(
                  product =>
                  renderProductCard(
                    product
                  )
                )
                .join("")
              }
            </div>

            ${totalPages > 1
              ?
              `
                <nav
                  class="catalog-pagination"
                  aria-label="${escapeAttribute(state.language === "en" ? "Catalog pages" : "Páginas del catálogo")}">

                  <button
                    class="catalog-page-btn"
                    type="button"
                    data-action="catalog-page"
                    data-page="${Math.max(1, state.catalogPage - 1)}"
                    ${state.catalogPage <= 1 ? "disabled" : ""}>
                    ←
                  </button>

                  ${pageButtons.join("")}

                  <button
                    class="catalog-page-btn"
                    type="button"
                    data-action="catalog-page"
                    data-page="${Math.min(totalPages, state.catalogPage + 1)}"
                    ${state.catalogPage >= totalPages ? "disabled" : ""}>
                    →
                  </button>

                  <div class="catalog-page-info">
                    ${state.language === "en"
                      ? `Showing ${pageStart + 1}–${Math.min(pageStart + pageSize, list.length)} of ${list.length}`
                      : `Mostrando ${pageStart + 1}–${Math.min(pageStart + pageSize, list.length)} de ${list.length}`
                    }
                  </div>
                </nav>
              `
              :
              ""
            }
          `
          :
          `
            <div class="empty-state">
              <h3>
                ${escapeHtml(t("catalog.empty"))}
              </h3>
            </div>
          `
        }
      </div>
    </section>
  `;
}

