    function productCartKey(
      productId
    )
    {
      return (
        "product:" +
        Number(
          productId
        )
      );
    }

    async function incrementPopularity(
      productId
    )
    {
      try
      {
        const result =
        await supabaseClient.rpc(
          "increment_product_popularity",
          {
            p_product_id:
            Number(
              productId
            ),
          }
        );

        if (
          result.error
        )
        {
          console.warn(
            "No se pudo registrar popularidad:",
            result.error.message
          );

          return;
        }

        const current =
        getPopularity(
          productId
        );

        state.popularity.set(
          Number(
            productId
          ),
          current + 1
        );
      }
      catch (
        error
      )
      {
        console.warn(
          "Popularidad:",
          error
        );
      }
    }

    function addProductToCart(
      productId
    )
    {
      const product =
      getProductById(
        productId
      );

      if (
        !product
      )
      {
        return;
      }

      if (
        product.stock <= 0
      )
      {
        toast(
          t(
            "product.out"
          ),
          "error"
        );

        return;
      }

      const key =
      productCartKey(
        product.id
      );

      const existing =
      state.cart.find(
        line =>
        line.key === key
      );

      if (
        existing
      )
      {
        if (
          existing.qty >= product.stock
        )
        {
          toast(
            state.language === "en"
            ?
            "No more stock is available."
            :
            "No hay más stock disponible.",
            "error"
          );

          return;
        }

        existing.qty +=
        1;
      }
      else
      {
        state.cart.push(
          {
            kind:
            "product",

            key:
            key,

            id:
            product.id,

            productId:
            product.id,

            qty:
            1,
          }
        );
      }

      saveLocalState();

      incrementPopularity(
        product.id
      );

      toast(
        state.language === "en"
        ?
        `${product.nombre} added to cart.`
        :
        `${product.nombre} agregado al carrito.`
      );

      openCart();
    }

    function getCartLineUnitPrice(
      line
    )
    {
      if (
        line.kind === "product"
      )
      {
        const product =
        getProductById(
          line.productId
          ??
          line.id
        );

        return product
        ?
        product.precio
        :
        0;
      }

      return asNumber(
        line.unitPrice,
        0
      );
    }

    function getCartLineTitle(
      line
    )
    {
      if (
        line.kind === "product"
      )
      {
        const product =
        getProductById(
          line.productId
          ??
          line.id
        );

        return product
        ?
        product.nombre
        :
        "Producto";
      }

      return String(
        line.title
        ||
        "Combo"
      );
    }

    function getCartLineImage(
      line
    )
    {
      if (
        line.kind === "product"
      )
      {
        const product =
        getProductById(
          line.productId
          ??
          line.id
        );

        return product
        ?
        getProductMainImage(
          product
        )
        :
        "";
      }

      if (
        line.image
      )
      {
        return line.image;
      }

      if (
        Array.isArray(
          line.items
        ) &&
        line.items.length
      )
      {
        const first =
        getProductById(
          line.items[0].productId
        );

        return first
        ?
        getProductMainImage(
          first
        )
        :
        "";
      }

      return "";
    }

    function getCartLineMeta(
      line
    )
    {
      if (
        line.kind === "product"
      )
      {
        const product =
        getProductById(
          line.productId
          ??
          line.id
        );

        if (
          !product
        )
        {
          return "";
        }

        return [
          product.ml
          ?
          `${product.ml} ml`
          :
          "",

          product.categoria,
        ]
        .filter(
          Boolean
        )
        .join(
          " · "
        );
      }

      if (
        line.bundleType === "decant"
      )
      {
        return (
          state.language === "en"
          ?
          `${line.items?.length || 0} decants`
          :
          `${line.items?.length || 0} decants`
        );
      }

      if (
        line.bundleType === "gift"
      )
      {
        return String(
          line.optionName
          ||
          t(
            "gifts.title"
          )
        );
      }

      return "";
    }

    function getCartSubtotal()
    {
      return state.cart.reduce(
        (
          total,
          line
        ) =>
        total +
        (
          getCartLineUnitPrice(
            line
          )
          *
          Math.max(
            1,
            asNumber(
              line.qty,
              1
            )
          )
        ),
        0
      );
    }

    function renderCart()
    {
      const itemsHost =
      document.getElementById(
        "cartItems"
      );

      const summaryHost =
      document.getElementById(
        "cartSummary"
      );

      if (
        !itemsHost ||
        !summaryHost
      )
      {
        return;
      }

      state.cart =
      state.cart.filter(
        line =>
        {
          if (
            line.kind !== "product"
          )
          {
            return true;
          }

          return Boolean(
            getProductById(
              line.productId
              ??
              line.id
            )
          );
        }
      );

      if (
        state.cart.length === 0
      )
      {
        itemsHost.innerHTML =
        `
          <div class="empty-state">
            <h3>
              ${escapeHtml(t("cart.empty"))}
            </h3>

            <button
              class="btn"
              type="button"
              data-route="catalog">
              ${escapeHtml(t("favorites.cta"))}
            </button>
          </div>
        `;

        summaryHost.innerHTML =
        "";

        saveLocalState();

        return;
      }

      itemsHost.innerHTML =
      state.cart
      .map(
        line =>
        renderCartLine(
          line
        )
      )
      .join(
        ""
      );

      summaryHost.innerHTML =
      `
        <div class="cart-summary">
          <div class="cart-total-row grand">
            <span>
              ${escapeHtml(t("cart.total"))}
            </span>

            <strong>
              ${money(getCartSubtotal())}
            </strong>
          </div>

          <button
            class="btn"
            style="width:100%;margin-top:10px"
            type="button"
            data-action="checkout">
            ${escapeHtml(t("cart.checkout"))}
          </button>
        </div>
      `;

      saveLocalState();
    }

    function renderCartLine(
      line
    )
    {
      const image =
      getCartLineImage(
        line
      );

      const title =
      getCartLineTitle(
        line
      );

      const meta =
      getCartLineMeta(
        line
      );

      const unitPrice =
      getCartLineUnitPrice(
        line
      );

      const qty =
      Math.max(
        1,
        asNumber(
          line.qty,
          1
        )
      );

      return `
        <article class="cart-line">
          <div class="cart-line-image">
            ${image
              ?
              `
                <img
                  src="${escapeAttribute(image)}"
                  alt="${escapeAttribute(title)}">
              `
              :
              `
                <span>
                  ✦
                </span>
              `
            }
          </div>

          <div>
            <h4>
              ${escapeHtml(title)}
            </h4>

            <div class="cart-line-meta">
              ${escapeHtml(meta)}
            </div>

            <div class="cart-line-meta">
              ${money(unitPrice)}
            </div>

            <div class="qty-control">
              <button
                type="button"
                data-action="cart-qty"
                data-cart-key="${escapeAttribute(line.key)}"
                data-delta="-1">
                −
              </button>

              <span>
                ${qty}
              </span>

              <button
                type="button"
                data-action="cart-qty"
                data-cart-key="${escapeAttribute(line.key)}"
                data-delta="1">
                +
              </button>
            </div>

            <button
              class="text-link"
              type="button"
              data-action="remove-cart-line"
              data-cart-key="${escapeAttribute(line.key)}">
              ${escapeHtml(t("cart.remove"))}
            </button>
          </div>

          <strong>
            ${money(unitPrice * qty)}
          </strong>
        </article>
      `;
    }

    function changeCartQuantity(
      key,
      delta
    )
    {
      const line =
      state.cart.find(
        item =>
        item.key === key
      );

      if (
        !line
      )
      {
        return;
      }

      const newQty =
      Math.max(
        0,
        asNumber(
          line.qty,
          1
        )
        +
        asNumber(
          delta,
          0
        )
      );

      if (
        newQty <= 0
      )
      {
        removeCartLine(
          key
        );

        return;
      }

      if (
        line.kind === "product"
      )
      {
        const product =
        getProductById(
          line.productId
          ??
          line.id
        );

        if (
          product &&
          newQty > product.stock
        )
        {
          toast(
            state.language === "en"
            ?
            "No more stock is available."
            :
            "No hay más stock disponible.",
            "error"
          );

          return;
        }
      }

      line.qty =
      newQty;

      saveLocalState();

      renderCart();
    }

    function removeCartLine(
      key
    )
    {
      state.cart =
      state.cart.filter(
        line =>
        line.key !== key
      );

      saveLocalState();

      renderCart();
    }

