    function openCheckout()
    {
      state.checkoutDiscount =
      null;

      if (
        state.cart.length === 0
      )
      {
        toast(
          t(
            "cart.empty"
          ),
          "error"
        );

        return;
      }

      closeCart();

      openModal(
        t(
          "checkout.title"
        ),
        renderCheckout()
      );
    }

    function getCheckedValue(
      name
    )
    {
      const checked =
      document.querySelector(
        `input[name="${name}"]:checked`
      );

      return checked
      ?
      checked.value
      :
      "";
    }

    function buildCartLineText(
      line
    )
    {
      const qty =
      Math.max(
        1,
        asNumber(
          line.qty,
          1
        )
      );

      const total =
      getCartLineUnitPrice(
        line
      )
      *
      qty;

      let text =
      "• " +
      getCartLineTitle(
        line
      )
      +
      " x" +
      qty
      +
      " — " +
      money(
        total
      );

      if (
        line.kind === "bundle" &&
        Array.isArray(
          line.items
        )
      )
      {
        const details =
        line.items.map(
          item =>
          {
            const product =
            getProductById(
              item.productId
            );

            return (
              "   - " +
              (
                product
                ?
                product.nombre
                :
                "Producto"
              )
              +
              (
                item.ml
                ?
                ` ${item.ml} ml`
                :
                ""
              )
              +
              (
                item.price
                ?
                ` (${money(item.price)})`
                :
                ""
              )
            );
          }
        )
        .join(
          "\n"
        );

        text +=
        "\n" +
        details;
      }

      return text;
    }

    async function validateGameDiscount()
    {
      const code =
      document.getElementById(
        "checkoutDiscountCode"
      )?.value.trim().toUpperCase()
      ||
      "";

      const phone =
      normalizeGamePhone(
        document.getElementById(
          "checkoutPhone"
        )?.value
      );

      if (
        !code ||
        phone.length < 8
      )
      {
        toast(
          state.language === "en"
          ?
          "Enter your WhatsApp number and discount code first."
          :
          "Ingresá primero tu WhatsApp y el código de descuento.",
          "error"
        );

        return;
      }

      const result =
      await supabaseClient.rpc(
        "validate_game_discount",
        {
          p_code:
          code,

          p_phone:
          phone,
        }
      );

      if (
        result.error
      )
      {
        state.checkoutDiscount =
        null;

        toast(
          result.error.message,
          "error"
        );

        return;
      }

      const data =
      result.data
      ||
      {};

      if (
        !data.valid
      )
      {
        state.checkoutDiscount =
        null;

        toast(
          data.message
          ||
          (
            state.language === "en"
            ?
            "Invalid or already used code."
            :
            "Código inválido, ajeno o ya utilizado."
          ),
          "error"
        );

        return;
      }

      state.checkoutDiscount =
      {
        code:
        data.code,

        percent:
        asNumber(
          data.percent,
          10
        ),

        phone:
        phone,

        rewardId:
        data.reward_id,
      };

      const modalBody =
      document.querySelector(
        ".modal-body"
      );

      if (
        modalBody
      )
      {
        modalBody.innerHTML =
        renderCheckout();

        const phoneInput =
        document.getElementById(
          "checkoutPhone"
        );

        if (
          phoneInput
        )
        {
          phoneInput.value =
          phone;
        }

        const codeInput =
        document.getElementById(
          "checkoutDiscountCode"
        );

        if (
          codeInput
        )
        {
          codeInput.value =
          code;
        }
      }

      toast(
        state.language === "en"
        ?
        "10% discount applied."
        :
        "Descuento del 10% aplicado.",
        "success"
      );
    }

    function sendWhatsAppOrder()
    {
      const name =
      document.getElementById(
        "checkoutName"
      )?.value.trim()
      ||
      "";

      const phone =
      document.getElementById(
        "checkoutPhone"
      )?.value.trim()
      ||
      "";

      const email =
      document.getElementById(
        "checkoutEmail"
      )?.value.trim()
      ||
      "";

      const payment =
      getCheckedValue(
        "checkoutPayment"
      );

      const shipping =
      getCheckedValue(
        "checkoutShipping"
      );

      if (
        !name ||
        !phone ||
        !email
      )
      {
        toast(
          state.language === "en"
          ?
          "Complete your name, phone and email."
          :
          "Completá nombre, teléfono y correo.",
          "error"
        );

        return;
      }

      if (
        state.checkoutDiscount &&
        normalizeGamePhone(
          phone
        ) !==
        normalizeGamePhone(
          state.checkoutDiscount.phone
        )
      )
      {
        state.checkoutDiscount =
        null;

        toast(
          state.language === "en"
          ?
          "The discount belongs to another WhatsApp number. Validate it again."
          :
          "El descuento pertenece a otro WhatsApp. Volvé a validarlo.",
          "error"
        );

        return;
      }

      const address =
      document.getElementById(
        "checkoutAddress"
      )?.value.trim()
      ||
      "";

      const city =
      document.getElementById(
        "checkoutCity"
      )?.value.trim()
      ||
      "";

      const province =
      document.getElementById(
        "checkoutProvince"
      )?.value.trim()
      ||
      "";

      const postal =
      document.getElementById(
        "checkoutPostal"
      )?.value.trim()
      ||
      "";

      if (
        shipping === "Sí" &&
        (
          !address ||
          !city ||
          !province
        )
      )
      {
        toast(
          state.language === "en"
          ?
          "Complete the shipping details."
          :
          "Completá los datos de envío.",
          "error"
        );

        return;
      }

      const lines =
      state.cart.map(
        line =>
        buildCartLineText(
          line
        )
      )
      .join(
        "\n"
      );

      let message =
      state.language === "en"
      ?
      `Hello, I would like to place this order.

CUSTOMER
Name: ${name}
Phone: ${phone}
Email: ${email}

PRODUCTS
${lines}

TOTAL: ${money(state.checkoutDiscount ? getCartSubtotal() * 0.90 : getCartSubtotal())}

PAYMENT
${payment}

SHIPPING
${shipping === "Sí" ? "Yes" : "No"}`
      :
      `Hola, quiero hacer este pedido.

DATOS DEL CLIENTE
Nombre: ${name}
Teléfono: ${phone}
Correo: ${email}

PRODUCTOS
${lines}

TOTAL: ${money(state.checkoutDiscount ? getCartSubtotal() * 0.90 : getCartSubtotal())}

MÉTODO DE PAGO
${payment}

¿CON ENVÍO?
${shipping}`;

      if (
        shipping === "Sí"
      )
      {
        message +=
        state.language === "en"
        ?
        `

SHIPPING DETAILS
Address: ${address}
City: ${city}
Province: ${province}
Postal code: ${postal || "Not provided"}`
        :
        `

DATOS DE ENVÍO
Dirección: ${address}
Ciudad: ${city}
Provincia: ${province}
Código postal: ${postal || "No indicado"}`;
      }

      if (
        state.checkoutDiscount
      )
      {
        message +=
        state.language === "en"
        ?
        `

DISCOUNT
Aroma Games winner: 10%
Code: ${state.checkoutDiscount.code}
Original subtotal: ${money(getCartSubtotal())}`
        :
        `

DESCUENTO
Ganador Aroma Games: 10%
Código: ${state.checkoutDiscount.code}
Subtotal original: ${money(getCartSubtotal())}`;
      }

      const whatsapp =
      getSiteSetting(
        "contact",
        "whatsapp",
        CONFIG.whatsappNumber
      );

      const url =
      "https://wa.me/" +
      String(
        whatsapp
      )
      .replace(
        /\D/g,
        ""
      )
      +
      "?text=" +
      encodeURIComponent(
        message
      );

      window.open(
        url,
        "_blank",
        "noopener"
      );
    }

    function toggleShippingFields()
    {
      const shipping =
      getCheckedValue(
        "checkoutShipping"
      );

      const fields =
      document.getElementById(
        "checkoutShippingFields"
      );

      if (
        !fields
      )
      {
        return;
      }

      fields.classList.toggle(
        "hidden",
        shipping !== "Sí"
      );
    }

    function toggleFavorite(
      productId
    )
    {
      const id =
      Number(
        productId
      );

      if (
        state.favorites.includes(
          id
        )
      )
      {
        state.favorites =
        state.favorites.filter(
          current =>
          current !== id
        );
      }
      else
      {
        state.favorites.push(
          id
        );
      }

      saveLocalState();

      renderCurrentRoute();
    }

function getDefaultDecantTemplate()
{
  return state.comboTemplates.find(
    template =>
    normalizeText(
      template.tipo
    ) ===
    "decants"
  )
  ||
  {
    id:
    null,

    nombre:
    t(
      "decants.title"
    ),

    max_productos:
    5,
  };
}

function getDecantEligibleProducts()
{
  const template =
  getDefaultDecantTemplate();

  const mappings =
  state.comboProducts.filter(
    row =>
    Number(
      row.combo_id
    ) ===
    Number(
      template.id
    )
  );

  if (
    mappings.length
  )
  {
    const allowed =
    new Set(
      mappings.map(
        row =>
        Number(
          row.product_id
        )
      )
    );

    return state.products.filter(
      product =>
      allowed.has(
        Number(
          product.id
        )
      )
      &&
      product.stock > 0
    );
  }

  return state.products.filter(
    product =>
    product.stock > 0
    &&
    (
      product.tipo_producto_slug === "perfume"
      ||
      normalizeText(
        product.tipo_producto
      ) ===
      "perfume"
    )
  );
}

function getDecantSizeRowsForProduct(
  productId
)
{
  const template =
  getDefaultDecantTemplate();

  const mapping =
  state.comboProducts.find(
    row =>
    Number(
      row.combo_id
    ) ===
    Number(
      template.id
    )
    &&
    Number(
      row.product_id
    ) ===
    Number(
      productId
    )
  );

  const allowed =
  mapping
  ?
  arrayFromDb(
    mapping.ml_opciones
  )
  .map(
    value =>
    asNumber(
      value,
      0
    )
  )
  .filter(
    value =>
    value > 0 &&
    value <= 30
  )
  :
  state.decantSizes
  .map(
    row =>
    asNumber(
      row.ml,
      0
    )
  )
  .filter(
    value =>
    value > 0 &&
    value <= 30
  );

  return uniqueStrings(
    allowed
  )
  .map(
    value =>
    asNumber(
      value,
      0
    )
  )
  .filter(
    value =>
    value > 0
  )
  .sort(
    (
      a,
      b
    ) =>
    a - b
  );
}

async function calculateDecantPrice(
  productId,
  ml
)
{
  const rpc =
  await supabaseClient.rpc(
    "calculate_decant_price",
    {
      p_product_id:
      Number(
        productId
      ),

      p_ml:
      Number(
        ml
      ),
    }
  );

  if (
    !rpc.error &&
    rpc.data !== null &&
    rpc.data !== undefined
  )
  {
    return asNumber(
      rpc.data,
      0
    );
  }

  const product =
  getProductById(
    productId
  );

  if (
    !product ||
    product.ml <= 0
  )
  {
    throw new Error(
      "No se pudo calcular el precio del decant."
    );
  }

  const sizeRow =
  state.decantSizes.find(
    row =>
    Number(
      row.ml
    ) ===
    Number(
      ml
    )
  )
  ||
  {
    factor:
    1,

    costo_envase:
    0,
  };

  const proportional =
  (
    product.precio /
    product.ml
  )
  *
  Number(
    ml
  )
  *
  asNumber(
    sizeRow.factor,
    1
  )
  +
  asNumber(
    sizeRow.costo_envase,
    0
  );

  return Math.ceil(
    proportional /
    100
  )
  *
  100;
}

