function renderDecantDraftSummary()
{
  if (
    state.decantDraft.length === 0
  )
  {
    return `
      <div class="empty-state">
        <h3>
          ${escapeHtml(t("decants.empty"))}
        </h3>
      </div>
    `;
  }

  const total =
  state.decantDraft.reduce(
    (
      sum,
      item
    ) =>
    sum +
    asNumber(
      item.price,
      0
    ),
    0
  );

  return `
    ${state.decantDraft
      .map(
        (
          item,
          index
        ) =>
        {
          const product =
          getProductById(
            item.productId
          );

          return `
            <div class="builder-summary-item">
              <span>
                ${escapeHtml(product?.nombre || "Perfume")}
                ·
                ${item.ml} ml
              </span>

              <span>
                ${money(item.price)}

                <button
                  type="button"
                  style="border:0;background:transparent;color:var(--danger)"
                  data-action="remove-decant"
                  data-index="${index}">
                  ×
                </button>
              </span>
            </div>
          `;
        }
      )
      .join("")
    }

    <div class="builder-total">
      <span>
        ${escapeHtml(t("decants.total"))}
      </span>

      <strong>
        ${money(total)}
      </strong>
    </div>

    <button
      class="btn u-mt-14"
      style="width:100%"
      type="button"
      data-action="add-decant-bundle-to-cart">
      ${escapeHtml(t("decants.cart"))}
    </button>
  `;
}

async function addDecantToDraft(
  productId
)
{
  const template =
  getDefaultDecantTemplate();

  const max =
  Math.max(
    1,
    asNumber(
      template.max_productos,
      5
    )
  );

  if (
    state.decantDraft.length >= max
  )
  {
    toast(
      t(
        "decants.limit"
      ),
      "error"
    );

    return;
  }

  const select =
  document.getElementById(
    "decantSize-" +
    productId
  );

  const ml =
  asNumber(
    select?.value,
    0
  );

  if (
    ml <= 0 ||
    ml > 30
  )
  {
    return;
  }

  try
  {
    const price =
    await calculateDecantPrice(
      productId,
      ml
    );

    state.decantDraft.push(
      {
        productId:
        Number(
          productId
        ),

        ml:
        ml,

        price:
        price,
      }
    );

    updateDecantSummaryOnly();
  }
  catch (
    error
  )
  {
    toast(
      error.message,
      "error"
    );
  }
}

function updateDecantSummaryOnly()
{
  const host =
  document.getElementById(
    "decantDraftSummary"
  );

  if (
    host
  )
  {
    host.innerHTML =
    renderDecantDraftSummary();
  }
}

function addDecantBundleToCart()
{
  if (
    state.decantDraft.length === 0
  )
  {
    return;
  }

  const items =
  state.decantDraft.map(
    item =>
    ({
      ...item,
    })
  );

  const total =
  items.reduce(
    (
      sum,
      item
    ) =>
    sum +
    asNumber(
      item.price,
      0
    ),
    0
  );

  const first =
  items[0]
  ?
  getProductById(
    items[0].productId
  )
  :
  null;

  state.cart.push(
    {
      kind:
      "bundle",

      bundleType:
      "decant",

      key:
      makeId(
        "decant"
      ),

      title:
      t(
        "decants.title"
      ),

      qty:
      1,

      unitPrice:
      total,

      items:
      items,

      image:
      first
      ?
      getProductMainImage(
        first
      )
      :
      "",
    }
  );

  state.decantDraft =
  [];

  saveLocalState();

  toast(
    state.language === "en"
    ?
    "Decant set added to cart."
    :
    "Combo de decants agregado al carrito."
  );

  renderCurrentRoute();

  openCart();
}

