function addGiftProductToDraft(
  productId
)
{
  const option =
  getCurrentGiftOption();

  const max =
  Math.max(
    1,
    asNumber(
      option.max_productos,
      4
    )
  );

  if (
    state.giftDraft.length >= max
  )
  {
    toast(
      t(
        "gifts.limit"
      ),
      "error"
    );

    return;
  }

  const product =
  getProductById(
    productId
  );

  if (
    !product
  )
  {
    return;
  }

  state.giftDraft.push(
    {
      productId:
      product.id,

      price:
      product.precio,
    }
  );

  updateGiftSummaryOnly();
}

function updateGiftSummaryOnly()
{
  const host =
  document.getElementById(
    "giftDraftSummary"
  );

  if (
    host
  )
  {
    host.innerHTML =
    renderGiftDraftSummary();
  }
}

function addGiftBundleToCart()
{
  if (
    state.giftDraft.length === 0
  )
  {
    return;
  }

  const option =
  getCurrentGiftOption();

  const items =
  state.giftDraft.map(
    item =>
    ({
      ...item,
    })
  );

  const total =
  items.reduce(
    (
      sum,
      item
    ) =>
    sum +
    asNumber(
      item.price,
      0
    ),
    0
  )
  +
  asNumber(
    option.precio_adicional,
    0
  );

  const first =
  items[0]
  ?
  getProductById(
    items[0].productId
  )
  :
  null;

  state.cart.push(
    {
      kind:
      "bundle",

      bundleType:
      "gift",

      key:
      makeId(
        "gift"
      ),

      title:
      t(
        "gifts.title"
      ),

      optionSlug:
      option.slug,

      optionName:
      state.language === "en"
      ?
      option.nombre_en
      :
      option.nombre_es,

      qty:
      1,

      unitPrice:
      total,

      items:
      items,

      image:
      first
      ?
      getProductMainImage(
        first
      )
      :
      "",
    }
  );

  state.giftDraft =
  [];

  saveLocalState();

  toast(
    state.language === "en"
    ?
    "Gift added to cart."
    :
    "Regalo agregado al carrito."
  );

  renderCurrentRoute();

  openCart();
}

function getGameConfig(
  type
)
{
  const config =
  state.gameConfigs.find(
    item =>
    item.tipo === type
  );

  if (
    config
  )
  {
    return config;
  }

  const fallback =
  {
    puzzle:
    {
      tipo:
      "puzzle",

      tiempo_limite:
      180,

      piezas:
      20,
    },

    differences:
    {
      tipo:
      "differences",

      tiempo_limite:
      180,

      diferencias:
      5,
    },

    hidden:
    {
      tipo:
      "hidden",

      tiempo_limite:
      90,
    },
  };

  return fallback[
    type
  ]
  ||
  fallback.puzzle;
}


function getGameAdsSettings()
{
  const ads =
  getSiteSettingObject(
    "game_ads"
  );

  return {
    enabled:
    ads.enabled === true,

    client:
    String(
      ads.client
      ||
      ""
    ).trim(),

    slotTop:
    String(
      ads.slot_top
      ||
      ""
    ).trim(),

    slotBottom:
    String(
      ads.slot_bottom
      ||
      ""
    ).trim(),
  };
}

function normalizeAdSenseClient(
  value
)
{
  const client =
  String(
    value
    ||
    ""
  ).trim();

  return /^ca-pub-\d{10,25}$/.test(
    client
  )
  ?
  client
  :
  "";
}

function normalizeAdSenseSlot(
  value
)
{
  const slot =
  String(
    value
    ||
    ""
  )
  .replace(
    /\D/g,
    ""
  )
  .slice(
    0,
    30
  );

  return slot;
}

function gameAdsReady()
{
  const ads =
  getGameAdsSettings();

  return Boolean(
    ads.enabled &&
    normalizeAdSenseClient(
      ads.client
    ) &&
    normalizeAdSenseSlot(
      ads.slotTop
    ) &&
    normalizeAdSenseSlot(
      ads.slotBottom
    )
  );
}

function renderGameAdSlot(
  position
)
{
  if (
    !gameAdsReady()
  )
  {
    return "";
  }

  const ads =
  getGameAdsSettings();

  const client =
  normalizeAdSenseClient(
    ads.client
  );

  const slot =
  position === "bottom"
  ?
  normalizeAdSenseSlot(
    ads.slotBottom
  )
  :
  normalizeAdSenseSlot(
    ads.slotTop
  );

  return `
    <aside
      class="game-ad-zone ${position === "bottom" ? "is-bottom" : ""}"
      aria-label="${state.language === "en" ? "Advertisement" : "Publicidad"}">
      <span class="game-ad-label">
        ${state.language === "en" ? "Advertisement" : "Publicidad"}
      </span>

      <ins
        class="adsbygoogle game-ad-unit"
        data-ad-client="${escapeAttribute(client)}"
        data-ad-slot="${escapeAttribute(slot)}"
        data-ad-format="horizontal"
        data-full-width-responsive="true"></ins>
    </aside>
  `;
}

function ensureGameAdsScript(
  client
)
{
  const validClient =
  normalizeAdSenseClient(
    client
  );

  if (
    !validClient
  )
  {
    return Promise.reject(
      new Error(
        "AdSense client inválido."
      )
    );
  }

  const existing =
  document.getElementById(
    "alpAdSenseScript"
  )
  ||
  Array.from(
    document.scripts
  ).find(
    script =>
    String(
      script.src
      ||
      ""
    ).includes(
      "pagead2.googlesyndication.com/pagead/js/adsbygoogle.js"
    )
  );

  if (
    existing
  )
  {
    return new Promise(
      resolve =>
      {
        if (
          existing.dataset.loaded === "true" ||
          document.readyState === "complete"
        )
        {
          resolve();

          return;
        }

        existing.addEventListener(
          "load",
          () => resolve(),
          {
            once:
            true,
          }
        );

        existing.addEventListener(
          "error",
          () => resolve(),
          {
            once:
            true,
          }
        );

        setTimeout(
          resolve,
          3500
        );
      }
    );
  }

  return new Promise(
    resolve =>
    {
      const script =
      document.createElement(
        "script"
      );

      script.id =
      "alpAdSenseScript";

      script.async =
      true;

      script.crossOrigin =
      "anonymous";

      script.src =
      "https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client="
      +
      encodeURIComponent(
        validClient
      );

      script.addEventListener(
        "load",
        () =>
        {
          script.dataset.loaded =
          "true";

          resolve();
        },
        {
          once:
          true,
        }
      );

      script.addEventListener(
        "error",
        () => resolve(),
        {
          once:
          true,
        }
      );

      document.head.appendChild(
        script
      );
    }
  );
}

async function activateGameAds()
{
  if (
    state.route !== "games" ||
    !gameAdsReady()
  )
  {
    return;
  }

  const ads =
  getGameAdsSettings();

  await ensureGameAdsScript(
    ads.client
  );

  document
  .querySelectorAll(
    ".game-ad-unit:not([data-alp-ad-loaded])"
  )
  .forEach(
    unit =>
    {
      unit.dataset.alpAdLoaded =
      "true";

      try
      {
        (
          window.adsbygoogle =
          window.adsbygoogle
          ||
          []
        ).push(
          {}
        );
      }
      catch (
        error
      )
      {
        console.warn(
          "AdSense:",
          error
        );
      }
    }
  );
}

