function normalizeGamePhone(
  value
)
{
  return String(
    value
    ||
    ""
  )
  .replace(
    /\D/g,
    ""
  );
}

function getGamePlayer()
{
  const player =
  state.gamePlayer
  ||
  null;

  if (
    !player
  )
  {
    return null;
  }

  const name =
  String(
    player.name
    ||
    ""
  ).trim();

  const phone =
  normalizeGamePhone(
    player.phone
  );

  if (
    name.length < 2 ||
    phone.length < 8
  )
  {
    return null;
  }

  return {
    name,
    phone,
  };
}

function saveGamePlayerFromForm()
{
  const name =
  document.getElementById(
    "gamePlayerName"
  )?.value.trim()
  ||
  "";

  const phone =
  normalizeGamePhone(
    document.getElementById(
      "gamePlayerPhone"
    )?.value
  );

  if (
    name.length < 2 ||
    phone.length < 8
  )
  {
    toast(
      state.language === "en"
      ?
      "Enter your name and a valid WhatsApp number."
      :
      "Ingresá tu nombre y un WhatsApp válido.",
      "error"
    );

    return;
  }

  state.gamePlayer =
  {
    name,
    phone,
  };

  localStorage.setItem(
    "alp_game_player",
    JSON.stringify(
      state.gamePlayer
    )
  );

  toast(
    state.language === "en"
    ?
    "Player saved."
    :
    "Jugador guardado.",
    "success"
  );

  renderCurrentRoute();
}

function clearGamePlayer()
{
  state.gamePlayer =
  null;

  localStorage.removeItem(
    "alp_game_player"
  );

  renderCurrentRoute();
}

async function loadDailyLeaderboard()
{
  try
  {
    const result =
    await supabaseClient.rpc(
      "get_daily_game_leaderboard",
      {
        p_date:
        null,
      }
    );

    if (
      result.error
    )
    {
      console.warn(
        "daily leaderboard:",
        result.error.message
      );

      state.dailyLeaderboard =
      [];

      return;
    }

    state.dailyLeaderboard =
    Array.isArray(
      result.data
    )
    ?
    result.data
    :
    [];
  }
  catch (
    error
  )
  {
    console.warn(
      "daily leaderboard:",
      error
    );

    state.dailyLeaderboard =
    [];
  }
}

async function submitDailyGameScore(
  completed,
  elapsed
)
{
  const player =
  getGamePlayer();

  if (
    !completed ||
    !player
  )
  {
    return null;
  }

  try
  {
    const result =
    await supabaseClient.rpc(
      "submit_daily_game_score",
      {
        p_player_name:
        player.name,

        p_player_phone:
        player.phone,

        p_game_type:
        state.game.type,

        p_product_id:
        Number(
          state.game.productId
        )
        ||
        null,

        p_duration_seconds:
        Math.max(
          1,
          Number(
            elapsed
          )
          ||
          1
        ),

        p_attempts:
        Math.max(
          1,
          Number(
            state.game.moves
          )
          ||
          1
        ),
      }
    );

    if (
      result.error
    )
    {
      console.warn(
        "submit_daily_game_score:",
        result.error.message
      );

      return null;
    }

    await loadDailyLeaderboard();

    return result.data
    ||
    null;
  }
  catch (
    error
  )
  {
    console.warn(
      "submit_daily_game_score:",
      error
    );

    return null;
  }
}

