function hiddenTileClick(
  index
)
{
  state.game.moves +=
  1;

  if (
    Number(
      index
    ) ===
    Number(
      state.game.hiddenTargetIndex
    )
  )
  {
    completeGame(
      true
    );

    return;
  }

  toast(
    state.language === "en"
    ?
    "Not that one. Keep looking."
    :
    "Ese no es. Seguí buscando.",
    "error",
    1400
  );
}

function formatGameTime(
  seconds
)
{
  const safe =
  Math.max(
    0,
    Math.floor(
      asNumber(
        seconds,
        0
      )
    )
  );

  const minutes =
  Math.floor(
    safe /
    60
  );

  const remainder =
  safe %
  60;

  return (
    String(
      minutes
    )
    .padStart(
      2,
      "0"
    )
    +
    ":" +
    String(
      remainder
    )
    .padStart(
      2,
      "0"
    )
  );
}

function afterRenderGame()
{
  clearGameTimer();

  if (
    state.route !== "game"
  )
  {
    return;
  }

  state.game.timerId =
  window.setInterval(
    () =>
    {
      state.game.remaining -=
      1;

      const time =
      document.getElementById(
        "gameTime"
      );

      if (
        time
      )
      {
        time.textContent =
        formatGameTime(
          state.game.remaining
        );
      }

      if (
        state.game.remaining <= 0
      )
      {
        completeGame(
          false
        );
      }
    },
    1000
  );
}

function clearGameTimer()
{
  if (
    state.game &&
    state.game.timerId
  )
  {
    clearInterval(
      state.game.timerId
    );

    state.game.timerId =
    null;
  }
}

async function completeGame(
  completed
)
{
  clearGameTimer();

  const elapsed =
  Math.max(
    0,
    Math.round(
      (
        Date.now() -
        (
          state.game.startedAt
          ||
          Date.now()
        )
      )
      /
      1000
    )
  );

  try
  {
    await supabaseClient.rpc(
      "register_game_result",
      {
        p_game_type:
        state.game.type,

        p_product_id:
        Number(
          state.game.productId
        ),

        p_completed:
        Boolean(
          completed
        ),

        p_duration_seconds:
        elapsed,

        p_attempts:
        Math.max(
          1,
          state.game.moves
        ),
      }
    );
  }
  catch (
    error
  )
  {
    console.warn(
      "game_activity:",
      error
    );
  }

  const scoreResult =
  await submitDailyGameScore(
    Boolean(
      completed
    ),
    elapsed
  );

  const points =
  scoreResult &&
  typeof scoreResult === "object"
  ?
  asNumber(
    scoreResult.points,
    0
  )
  :
  0;

  const solvedToday =
  scoreResult &&
  typeof scoreResult === "object"
  ?
  asNumber(
    scoreResult.solved_today,
    0
  )
  :
  0;

  openModal(
    completed
    ?
    t(
      "games.win"
    )
    :
    t(
      "games.lose"
    ),
    `
      <div class="empty-state">
        <h3>
          ${escapeHtml(
            completed
            ?
            t("games.win")
            :
            t("games.lose")
          )}
        </h3>

        <p>
          ${escapeHtml(t("games.time"))}:
          ${formatGameTime(elapsed)}
        </p>

        ${completed && points
          ?
          `
            <div class="game-score-earned">
              <strong>+${formatInteger(points)}</strong>
              <span>
                ${state.language === "en" ? "points earned" : "puntos ganados"}
              </span>
            </div>

            <p class="u-mt-14">
              ${state.language === "en"
                ? `Solved today: ${formatInteger(solvedToday)}`
                : `Resueltos hoy: ${formatInteger(solvedToday)}`
              }
            </p>
          `
          :
          ""
        }

        <div class="u-flex-center-gap u-mt-14">
          <button
            class="btn"
            type="button"
            data-action="restart-game">
            ${escapeHtml(t("games.restart"))}
          </button>

          <button
            class="btn secondary"
            type="button"
            data-route="games">
            ${state.language === "en" ? "See ranking" : "Ver ranking"}
          </button>
        </div>
      </div>
    `
  );
}

function restartGame()
{
  const type =
  state.game.type;

  if (
    !type
  )
  {
    setRoute(
      "games"
    );

    return;
  }

  startGame(
    type
  );
}

    function getAiCatalogPayload()
    {
      return state.products
      .filter(
        product =>
        product.stock > 0
      )
      .slice(
        0,
        150
      )
      .map(
        product =>
        ({
          id:
          product.id,

          nombre:
          product.nombre,

          marca:
          product.marca,

          precio:
          product.precio,

          ml:
          product.ml,

          categoria:
          product.categoria,

          genero:
          product.genero,

          familia:
          product.familia,

          salida:
          product.salida,

          corazon:
          product.corazon,

          fondo:
          product.fondo,

          descripcion:
          product.descripcion,

          stock:
          product.stock,

          estaciones:
          product.estaciones,

          ocasiones:
          product.ocasiones,

          duracion:
          product.duracion,

          proyeccion:
          product.proyeccion,
        })
      );
    }

    async function callAromaAI(
      mode,
      payload = {}
    )
    {
      const endpoint =
      getAiEndpoint();

      const result =
      await supabaseClient.functions.invoke(
        endpoint,
        {
          body:
          {
            mode:
            mode,

            ...payload,
          },
        }
      );

      if (
        result.error
      )
      {
        throw new Error(
          result.error.message
          ||
          "Error de la función de IA."
        );
      }

      const data =
      result.data
      ||
      {};

      if (
        data.success === false
      )
      {
        throw new Error(
          data.error
          ||
          "La IA devolvió un error."
        );
      }

      return data.result;
    }

