    async function sendAdvisorMessage()
    {
      if (
        !isAiEnabled(
          "advisor_enabled"
        )
      )
      {
        toast(
          t(
            "advisor.disabled"
          ),
          "error"
        );

        return;
      }

      const input =
      document.getElementById(
        "advisorInput"
      );

      const message =
      input?.value.trim()
      ||
      "";

      if (
        !message
      )
      {
        return;
      }

      state.advisorMessages.push(
        {
          role:
          "user",

          text:
          message,
        }
      );

      if (
        input
      )
      {
        input.value =
        "";
      }

      const host =
      document.getElementById(
        "advisorMessages"
      );

      if (
        host
      )
      {
        host.innerHTML =
        renderAdvisorMessages(
          true
        )
        +
        `
          <div class="chat-bubble ai">
            ${escapeHtml(t("common.loading"))}
          </div>
        `;
      }

      try
      {
        const result =
        await callAromaAI(
          "advisor",
          {
            message:
            message,

            products:
            getAiCatalogPayload(),
          }
        );

        state.advisorMessages.push(
          {
            role:
            "ai",

            text:
            typeof result === "string"
            ?
            result
            :
            JSON.stringify(
              result,
              null,
              2
            ),
          }
        );
      }
      catch (
        error
      )
      {
        state.advisorMessages.push(
          {
            role:
            "ai",

            text:
            state.language === "en"
            ?
            `The advisor could not answer: ${error.message}`
            :
            `El asesor no pudo responder: ${error.message}`,
          }
        );
      }

      renderCurrentRoute();
    }

