async function upsertSiteSetting(
  key,
  value
)
{
  const result =
  await supabaseClient
    .from(
      "site_settings"
    )
    .upsert(
      {
        key:
        key,

        value:
        value,

        updated_at:
        new Date().toISOString(),
      },
      {
        onConflict:
        "key",
      }
    )
    .select(
      "key,value"
    )
    .single();

  if (
    result.error
  )
  {
    throw result.error;
  }

  state.siteSettings[
    key
  ] =
  result.data.value
  ||
  value;

  return result.data;
}

