async function saveGameAdsSettings()
{
  try
  {
    const enabled =
    getInputChecked(
      "setting-game-ads-enabled"
    );

    const clientRaw =
    getInputValue(
      "setting-game-ads-client"
    );

    const slotTop =
    normalizeAdSenseSlot(
      getInputValue(
        "setting-game-ads-slot-top"
      )
    );

    const slotBottom =
    normalizeAdSenseSlot(
      getInputValue(
        "setting-game-ads-slot-bottom"
      )
    );

    const client =
    clientRaw
    ?
    normalizeAdSenseClient(
      clientRaw
    )
    :
    "";

    if (
      enabled &&
      !client
    )
    {
      throw new Error(
        "El ID de AdSense debe tener formato ca-pub-..."
      );
    }

    if (
      enabled &&
      (
        !slotTop ||
        !slotBottom
      )
    )
    {
      throw new Error(
        "Ingresá los dos IDs de bloque de anuncios."
      );
    }

    await upsertSiteSetting(
      "game_ads",
      {
        enabled:
        enabled,

        client:
        client,

        slot_top:
        slotTop,

        slot_bottom:
        slotBottom,
      }
    );

    adminMessage(
      enabled
      ?
      "Publicidad de Juegos guardada. Los anuncios se mostrarán cuando AdSense tenga tu sitio y bloques habilitados."
      :
      "Publicidad de Juegos desactivada.",
      "ok"
    );

    refreshAdminTab();
  }
  catch (
    error
  )
  {
    adminMessage(
      error.message,
      "error"
    );
  }
}

function sanitizeVideoExtension(
  file
)
{
  const fileName =
  String(
    file?.name
    ||
    ""
  );

  const byName =
  fileName.includes(".")
  ?
  fileName
  .split(".")
  .pop()
  .toLowerCase()
  .replace(
    /[^a-z0-9]/g,
    ""
  )
  :
  "";

  if (
    ["mp4", "webm", "mov"].includes(
      byName
    )
  )
  {
    return byName;
  }

  if (
    file?.type === "video/webm"
  )
  {
    return "webm";
  }

  if (
    file?.type === "video/quicktime"
  )
  {
    return "mov";
  }

  return "mp4";
}

async function uploadSeasonalVideoFile(
  file
)
{
  if (
    !file ||
    !String(
      file.type
      ||
      ""
    ).startsWith(
      "video/"
    )
  )
  {
    throw new Error(
      "Seleccioná un archivo de video válido."
    );
  }

  const maxVideoBytes =
  50 * 1024 * 1024;

  if (
    file.size > maxVideoBytes
  )
  {
    throw new Error(
      "El video puede pesar como máximo 50 MB."
    );
  }

  const extension =
  sanitizeVideoExtension(
    file
  );

  const path =
  "site-media/seasonal/" +
  makeId(
    "video"
  ) +
  "." +
  extension;

  const upload =
  await supabaseClient
    .storage
    .from(
      CONFIG.storageBucket
    )
    .upload(
      path,
      file,
      {
        upsert:
        false,

        contentType:
        file.type
        ||
        "video/mp4",

        cacheControl:
        "31536000",
      }
    );

  if (
    upload.error
  )
  {
    throw upload.error;
  }

  const previous =
  getSiteSettingObject(
    "seasonal_video"
  );

  const previousPath =
  normalizeStoragePath(
    previous.path
    ||
    ""
  );

  const next =
  {
    ...previous,

    enabled:
    true,

    source_type:
    "upload",

    path:
    path,

    url:
    "",

    title_es:
    getInputValue(
      "setting-video-title-es"
    )
    ||
    previous.title_es
    ||
    "Perfumes de temporada",

    title_en:
    getInputValue(
      "setting-video-title-en"
    )
    ||
    previous.title_en
    ||
    "Seasonal Fragrances",

    autoplay:
    getInputChecked(
      "setting-video-autoplay"
    ),

    muted:
    getInputChecked(
      "setting-video-muted"
    ),

    loop:
    getInputChecked(
      "setting-video-loop"
    ),
  };

  try
  {
    await upsertSiteSetting(
      "seasonal_video",
      next
    );
  }
  catch (
    error
  )
  {
    await supabaseClient
      .storage
      .from(
        CONFIG.storageBucket
      )
      .remove(
        [
          path,
        ]
      );

    throw error;
  }

  if (
    previousPath.kind === "storage" &&
    previousPath.value &&
    previousPath.value !== path
  )
  {
    const removeOld =
    await supabaseClient
      .storage
      .from(
        CONFIG.storageBucket
      )
      .remove(
        [
          previousPath.value,
        ]
      );

    if (
      removeOld.error
    )
    {
      console.warn(
        "No se pudo borrar el video anterior:",
        removeOld.error.message
      );
    }
  }

  await loadSeasonalVideoUrl();
}

