function sanitizeCoverSlot(
  value
)
{
  return String(
    value || "cover"
  )
  .toLowerCase()
  .replace(
    /[^a-z0-9_-]/g,
    "-"
  )
  .slice(
    0,
    80
  )
  ||
  "cover";
}

async function uploadSiteCoverFile(
  slot,
  file,
  settingKey = "cover_images"
)
{
  if (
    !file ||
    !String(file.type || "").startsWith("image/")
  )
  {
    throw new Error(
      "Seleccioná un archivo de imagen válido."
    );
  }

  if (
    file.size > CONFIG.maxImageBytes
  )
  {
    throw new Error(
      "La imagen puede pesar como máximo 8 MB."
    );
  }

  const safeSlot =
  sanitizeCoverSlot(
    slot
  );

  const uploadFile =
  await optimizeImageForUpload(
    file,
    {
      maxWidth: 1600,
      maxHeight: 1200,
      quality: 0.82,
    }
  );

  const extension =
  sanitizeFileExtension(
    uploadFile
  );

  const path =
  "portadas/" +
  safeSlot +
  "/" +
  makeId("cover") +
  "." +
  extension;

  const upload =
  await supabaseClient
    .storage
    .from(
      CONFIG.storageBucket
    )
    .upload(
      path,
      uploadFile,
      {
        upsert: false,
        contentType: uploadFile.type,
        cacheControl: "31536000",
      }
    );

  if (upload.error)
  {
    throw upload.error;
  }

  const settings =
  {
    ...getSiteSettingObject(
      settingKey
    ),
  };

  const previous =
  settings[slot]
  ||
  "";

  settings[slot] =
  path;

  try
  {
    await upsertSiteSetting(
      settingKey,
      settings
    );
  }
  catch (error)
  {
    await supabaseClient
      .storage
      .from(
        CONFIG.storageBucket
      )
      .remove([path]);

    throw error;
  }

  const previousNormalized =
  normalizeStoragePath(
    previous
  );

  if (
    previousNormalized.kind === "storage" &&
    previousNormalized.value &&
    previousNormalized.value !== path
  )
  {
    const removeOld =
    await supabaseClient
      .storage
      .from(
        CONFIG.storageBucket
      )
      .remove([
        previousNormalized.value,
      ]);

    if (removeOld.error)
    {
      console.warn(
        "No se pudo eliminar la portada anterior:",
        removeOld.error.message
      );
    }
  }

  await loadSiteCoverUrls();
}

async function saveSiteCoverUrl(
  slot
)
{
  try
  {
    const value =
    getInputValue(
      `cover-url-${slot}`
    );

    if (
      value &&
      !/^https?:\/\//i.test(value)
    )
    {
      throw new Error(
        "La URL debe comenzar con http:// o https://"
      );
    }

    const settings =
    {
      ...getSiteSettingObject(
        "cover_images"
      ),
    };

    const previous =
    settings[slot]
    ||
    "";

    if (value)
    {
      settings[slot] = value;
    }
    else
    {
      delete settings[slot];
    }

    await upsertSiteSetting(
      "cover_images",
      settings
    );

    const previousNormalized =
    normalizeStoragePath(
      previous
    );

    if (
      previousNormalized.kind === "storage" &&
      previousNormalized.value
    )
    {
      await supabaseClient
        .storage
        .from(
          CONFIG.storageBucket
        )
        .remove([
          previousNormalized.value,
        ]);
    }

    await loadSiteCoverUrls();

    refreshAdminTab();

    adminMessage(
      "Portada actualizada.",
      "ok"
    );
  }
  catch (error)
  {
    adminMessage(
      error.message,
      "error"
    );
  }
}

