async function saveAdminGame(
  gameId
)
{
  const config =
  state.gameConfigs.find(
    item =>
    Number(
      item.id
    ) ===
    Number(
      gameId
    )
  );

  if (
    !config
  )
  {
    return;
  }

  const payload =
  {
    tiempo_limite:
    Math.max(
      10,
      getInputNumber(
        `game-time-${gameId}`,
        config.tiempo_limite
      )
    ),

    updated_at:
    new Date().toISOString(),
  };

  if (
    config.tipo === "puzzle"
  )
  {
    payload.piezas =
    20;
  }

  if (
    config.tipo === "differences"
  )
  {
    payload.diferencias =
    5;
  }

  const result =
  await supabaseClient
    .from(
      "aroma_games"
    )
    .update(
      payload
    )
    .eq(
      "id",
      Number(
        gameId
      )
    );

  if (
    result.error
  )
  {
    adminMessage(
      result.error.message,
      "error"
    );

    return;
  }

  await loadGameConfigs();

  refreshAdminTab();

  adminMessage(
    state.language === "en"
    ?
    "Game settings saved."
    :
    "Configuración del juego guardada.",
    "ok"
  );
}

