async function fillNewProductWithAI()
{
  if (
    !isAiEnabled(
      "admin_assistant_enabled"
    )
  )
  {
    adminMessage(
      t(
        "admin.ai.disabled"
      ),
      "error"
    );

    return;
  }

  const perfumeName =
  getInputValue(
    "adminAiPerfumeName"
  );

  if (
    !perfumeName
  )
  {
    adminMessage(
      state.language === "en"
      ?
      "Enter a fragrance name."
      :
      "Escribí el nombre de una fragancia.",
      "error"
    );

    return;
  }

  adminMessage(
    state.language === "en"
    ?
    "Consulting AI..."
    :
    "Consultando IA...",
    "ok"
  );

  try
  {
    const result =
    await callAromaAI(
      "admin",
      {
        perfumeName:
        perfumeName,
      }
    );

    const data =
    typeof result === "string"
    ?
    safeJsonParse(
      result,
      null
    )
    :
    result;

    if (
      !data ||
      typeof data !== "object"
    )
    {
      throw new Error(
        state.language === "en"
        ?
        "AI did not return a valid product sheet."
        :
        "La IA no devolvió una ficha válida."
      );
    }

    state.admin.aiDraft =
    data;

    setInputIfExists(
      "np-name",
      data.nombre
    );

    setInputIfExists(
      "np-brand",
      data.marca
    );

    setInputIfExists(
      "np-category",
      data.categoria
    );

    setInputIfExists(
      "np-gender",
      data.genero
    );

    setInputIfExists(
      "np-family",
      data.familia
    );

    setInputIfExists(
      "np-description",
      data.descripcion
    );

    setInputIfExists(
      "np-top",
      data.salida
    );

    setInputIfExists(
      "np-heart",
      data.corazon
    );

    setInputIfExists(
      "np-base",
      data.fondo
    );

    setInputIfExists(
      "np-ml",
      data.ml
    );

    setInputIfExists(
      "np-duration",
      data.duracion
    );

    setInputIfExists(
      "np-projection",
      data.proyeccion
    );

    setInputIfExists(
      "np-use",
      data.recomendacion_uso
    );

    setInputIfExists(
      "np-seasons",
      Array.isArray(
        data.estaciones
      )
      ?
      data.estaciones.join(
        ", "
      )
      :
      data.estaciones
    );

    setInputIfExists(
      "np-occasions",
      Array.isArray(
        data.ocasiones
      )
      ?
      data.ocasiones.join(
        ", "
      )
      :
      data.ocasiones
    );

    const createdAi =
    document.getElementById(
      "np-created-ai"
    );

    if (
      createdAi
    )
    {
      createdAi.checked =
      true;
    }

    const imageSearch =
    document.getElementById(
      "adminAiImageSearch"
    );

    if (
      imageSearch &&
      data.imagen_query
    )
    {
      imageSearch.innerHTML =
      `
        <p class="section-subtitle">
          Búsqueda sugerida:
          <strong>
            ${escapeHtml(data.imagen_query)}
          </strong>
        </p>

        <button
          class="btn outline small"
          type="button"
          data-action="admin-open-image-search"
          data-image-query="${escapeAttribute(data.imagen_query)}">
          Buscar imagen
        </button>
      `;
    }

    adminMessage(
      state.language === "en"
      ?
      "AI completed the draft. Review everything before saving."
      :
      "La IA completó el borrador. Revisá todo antes de guardar.",
      "ok"
    );
  }
  catch (
    error
  )
  {
    adminMessage(
      error.message,
      "error"
    );
  }
}

function setInputIfExists(
  id,
  value
)
{
  const element =
  document.getElementById(
    id
  );

  if (
    !element ||
    value === undefined ||
    value === null
  )
  {
    return;
  }

  element.value =
  String(
    value
  );
}

async function fillExistingProductWithAI(
  productId
)
{
  const product =
  getProductById(
    productId
  );

  if (
    !product
  )
  {
    return;
  }

  if (
    !isAiEnabled(
      "admin_assistant_enabled"
    )
  )
  {
    adminMessage(
      t(
        "admin.ai.disabled"
      ),
      "error"
    );

    return;
  }

  try
  {
    const result =
    await callAromaAI(
      "admin",
      {
        perfumeName:
        product.nombre,
      }
    );

    const data =
    typeof result === "string"
    ?
    safeJsonParse(
      result,
      null
    )
    :
    result;

    if (
      !data
    )
    {
      throw new Error(
        "Respuesta inválida."
      );
    }

    setInputIfExists(
      `ap-brand-${product.id}`,
      data.marca
    );

    setInputIfExists(
      `ap-category-${product.id}`,
      data.categoria
    );

    setInputIfExists(
      `ap-gender-${product.id}`,
      data.genero
    );

    setInputIfExists(
      `ap-family-${product.id}`,
      data.familia
    );

    setInputIfExists(
      `ap-description-${product.id}`,
      data.descripcion
    );

    setInputIfExists(
      `ap-top-${product.id}`,
      data.salida
    );

    setInputIfExists(
      `ap-heart-${product.id}`,
      data.corazon
    );

    setInputIfExists(
      `ap-base-${product.id}`,
      data.fondo
    );

    setInputIfExists(
      `ap-duration-${product.id}`,
      data.duracion
    );

    setInputIfExists(
      `ap-projection-${product.id}`,
      data.proyeccion
    );

    setInputIfExists(
      `ap-seasons-${product.id}`,
      Array.isArray(
        data.estaciones
      )
      ?
      data.estaciones.join(
        ", "
      )
      :
      data.estaciones
    );

    setInputIfExists(
      `ap-occasions-${product.id}`,
      Array.isArray(
        data.ocasiones
      )
      ?
      data.ocasiones.join(
        ", "
      )
      :
      data.ocasiones
    );

    adminMessage(
      state.language === "en"
      ?
      "AI filled the row. Review it and press Save."
      :
      "La IA completó la fila. Revisala y tocá Guardar.",
      "ok"
    );
  }
  catch (
    error
  )
  {
    adminMessage(
      error.message,
      "error"
    );
  }
}

function openImageSearch(
  query
)
{
  const q =
  String(
    query
    ||
    ""
  )
  .trim();

  if (
    !q
  )
  {
    return;
  }

  window.open(
    "https://www.google.com/search?tbm=isch&q=" +
    encodeURIComponent(
      q
    ),
    "_blank",
    "noopener"
  );
}

    function openSearchModal()
    {
      openModal(
        state.language === "en"
        ?
        "Search fragrances"
        :
        "Buscar perfumes",
        `
          <div class="admin-form">
            <input
              id="globalSearchInput"
              class="search-input"
              type="search"
              placeholder="${escapeAttribute(t("catalog.search"))}"
              autofocus>

            <button
              class="btn"
              type="button"
              data-action="global-search-submit">
              ${state.language === "en" ? "Search" : "Buscar"}
            </button>
          </div>
        `
      );

      window.setTimeout(
        () =>
        {
          document.getElementById(
            "globalSearchInput"
          )?.focus();
        },
        30
      );
    }

    function submitGlobalSearch()
    {
      const value =
      document.getElementById(
        "globalSearchInput"
      )?.value.trim()
      ||
      "";

      state.catalogSearch =
      value;

      state.catalogFilter =
      "Todos";

      state.catalogPage =
      1;

      setRoute(
        "catalog"
      );
    }

    function handleRouteElement(
      element
    )
    {
      const route =
      element.dataset.route;

      if (
        !route
      )
      {
        return false;
      }

      if (
        route === "admin" &&
        document.body?.dataset.entry !== "admin"
      )
      {
        window.location.href = "admin/";
        return true;
      }

      if (
        route !== "admin" &&
        document.body?.dataset.entry === "admin"
      )
      {
        window.location.href = "../";
        return true;
      }

      if (
        route === "catalog"
      )
      {
        state.catalogFilter =
        element.dataset.filter
        ||
        "Todos";

        state.catalogPage =
        1;
      }

      if (
        route === "product"
      )
      {
        state.selectedGalleryUrl =
        "";

        setRoute(
          "product",
          {
            id:
            Number(
              element.dataset.productId
            ),
          }
        );

        return true;
      }

      if (
        route === "collection"
      )
      {
        setRoute(
          "collection",
          {
            slug:
            element.dataset.collectionSlug
            ||
            "",
          }
        );

        return true;
      }

      setRoute(
        route
      );

      return true;
    }

    async function handleAction(
      element
    )
    {
      const action =
      element.dataset.action;

      if (
        !action
      )
      {
        return;
      }

      switch (
        action
      )
      {
        case "home":
        {
          setRoute(
            "home"
          );

          break;
        }

        case "open-menu":
        {
          openMenu();

          break;
        }

        case "close-menu":
        {
          closeMenu();

          break;
        }

        case "open-cart":
        {
          openCart();

          break;
        }

        case "close-cart":
        {
          closeCart();

          break;
        }

        case "close-modal":
        {
          closeModal();

          break;
        }

        case "open-search":
        {
          openSearchModal();

          break;
        }

        case "global-search-submit":
        {
          submitGlobalSearch();

          break;
        }

        case "select-hero-collection":
        {
          state.heroCollectionIndex =
          clamp(
            asNumber(
              element.dataset.index,
              0
            ),
            0,
            Math.max(
              0,
              getHeroCollections().length - 1
            )
          );

          renderCurrentRoute();

          break;
        }

        case "toggle-favorite":
        {
          toggleFavorite(
            element.dataset.productId
          );

          break;
        }

        case "add-product":
        {
          addProductToCart(
            element.dataset.productId
          );

          break;
        }

        case "cart-qty":
        {
          changeCartQuantity(
            element.dataset.cartKey,
            asNumber(
              element.dataset.delta,
              0
            )
          );

          break;
        }

        case "remove-cart-line":
        {
          removeCartLine(
            element.dataset.cartKey
          );

          break;
        }

        case "checkout":
        {
          openCheckout();

          break;
        }

        case "validate-game-discount":
        {
          await validateGameDiscount();

          break;
        }

        case "send-whatsapp-order":
        {
          sendWhatsAppOrder();

          break;
        }

        case "shipping-choice":
        {
          toggleShippingFields();

          break;
        }

        case "catalog-filter":
        {
          state.catalogFilter =
          element.dataset.filter
          ||
          "Todos";

          state.catalogPage =
          1;

          renderCurrentRoute();

          break;
        }

        case "catalog-page":
        {
          state.catalogPage =
          Math.max(
            1,
            asNumber(
              element.dataset.page,
              1
            )
          );

          renderCurrentRoute();

          window.scrollTo(
            {
              top:
              0,

              behavior:
              "smooth",
            }
          );

          break;
        }

        case "clear-catalog":
        {
          state.catalogFilter =
          "Todos";

          state.catalogSearch =
          "";

          state.catalogSort =
          "default";

          state.catalogPage =
          1;

          renderCurrentRoute();

          break;
        }

        case "select-gallery-image":
        {
          state.selectedGalleryUrl =
          element.dataset.imageUrl
          ||
          "";

          renderCurrentRoute();

          break;
        }

        case "add-decant":
        {
          await addDecantToDraft(
            element.dataset.productId
          );

          break;
        }

        case "remove-decant":
        {
          const index =
          asNumber(
            element.dataset.index,
            -1
          );

          if (
            index >= 0
          )
          {
            state.decantDraft.splice(
              index,
              1
            );

            updateDecantSummaryOnly();
          }

          break;
        }

        case "add-decant-bundle-to-cart":
        {
          addDecantBundleToCart();

          break;
        }

        case "add-gift-product":
        {
          addGiftProductToDraft(
            element.dataset.productId
          );

          break;
        }

        case "remove-gift-product":
        {
          const index =
          asNumber(
            element.dataset.index,
            -1
          );

          if (
            index >= 0
          )
          {
            state.giftDraft.splice(
              index,
              1
            );

            updateGiftSummaryOnly();
          }

          break;
        }

        case "add-gift-bundle-to-cart":
        {
          addGiftBundleToCart();

          break;
        }

        case "save-game-player":
        {
          saveGamePlayerFromForm();

          break;
        }

        case "clear-game-player":
        {
          clearGamePlayer();

          break;
        }

        case "start-game":
        {
          await startGame(
            element.dataset.gameType
          );

          break;
        }

        case "restart-game":
        {
          closeModal();

          restartGame();

          break;
        }

        case "puzzle-piece":
        {
          puzzlePieceClick(
            element.dataset.index
          );

          break;
        }

        case "difference-zone":
        {
          findDifference(
            element.dataset.differenceId
          );

          break;
        }

        case "hidden-tile":
        {
          hiddenTileClick(
            element.dataset.index
          );

          break;
        }

        case "advisor-send":
        {
          await sendAdvisorMessage();

          break;
        }

        case "advisor-prompt":
        {
          const input =
          document.getElementById(
            "advisorInput"
          );

          if (
            input
          )
          {
            input.value =
            element.dataset.prompt
            ||
            "";

            input.focus();
          }

          break;
        }

        case "open-whatsapp":
        {
          openWhatsAppGeneral();

          break;
        }

        case "send-contact-whatsapp":
        {
          sendContactWhatsApp();

          break;
        }

        case "reload-data":
        {
          await loadAllData();

          break;
        }

        case "admin-login":
        {
          await adminLogin();

          break;
        }

        case "admin-recover":
        {
          await adminRecoverPassword();

          break;
        }

        case "admin-logout":
        {
          await adminLogout();

          break;
        }

        case "admin-reload":
        {
          await reloadAdminData();
          break;
        }

        case "admin-product-page":
        {
          state.admin.productPage =
          Math.max(
            1,
            Number(element.dataset.page) || 1
          );

          refreshAdminTab();
          break;
        }

        case "admin-load-gallery":
        {
          const productId =
          Number(element.dataset.productId);

          element.disabled = true;
          element.textContent =
          state.language === "en" ? "Loading..." : "Cargando...";

          await ensureProductGallery(productId);
          updateAdminPhotoCell(productId);
          break;
        }

        case "admin-tab":
        {
          state.admin.tab =
          element.dataset.tab
          ||
          "products";

          if (
            state.admin.tab === "games"
          )
          {
            await loadGameRewardsAdmin();
          }

          refreshAdminTab();

          break;
        }

        case "admin-award-yesterday":
        {
          await awardYesterdayGameWinner();

          break;
        }

        case "admin-send-game-reward":
        {
          sendGameRewardWhatsApp(
            element.dataset.rewardId
          );

          break;
        }

        case "admin-mark-game-reward-sent":
        {
          await updateGameRewardStatus(
            element.dataset.rewardId,
            "sent"
          );

          break;
        }

        case "admin-mark-game-reward-used":
        {
          await updateGameRewardStatus(
            element.dataset.rewardId,
            "used"
          );

          break;
        }

        case "admin-create-product":
        {
          await createProductFromAdmin();

          break;
        }

        case "admin-save-product":
        {
          await saveAdminProduct(
            element.dataset.productId
          );

          break;
        }

        case "admin-delete-product":
        {
          await deleteAdminProduct(
            element.dataset.productId
          );

          break;
        }

        case "admin-delete-photo":
        {
          await deleteAdminPhoto(
            element.dataset.imageId,
            element.dataset.productId,
            element.dataset.storagePath
          );

          break;
        }

        case "admin-ai-new":
        {
          await fillNewProductWithAI();

          break;
        }

        case "admin-ai-existing":
        {
          await fillExistingProductWithAI(
            element.dataset.productId
          );

          break;
        }

        case "admin-open-image-search":
        {
          openImageSearch(
            element.dataset.imageQuery
          );

          break;
        }

        case "admin-save-contact-settings":
        {
          await saveContactSettings();

          break;
        }

        case "admin-save-shipping-settings":
        {
          await saveShippingSettings();

          break;
        }

        case "admin-save-game-ads-settings":
        {
          await saveGameAdsSettings();

          break;
        }

        case "admin-save-video-settings":
        {
          await saveVideoSettings();

          break;
        }

        case "admin-delete-seasonal-video":
        {
          await deleteSeasonalVideo();

          break;
        }

        case "admin-save-ai-settings":
        {
          await saveAiSettings();

          break;
        }

        case "admin-save-cover-url":
        {
          await saveSiteCoverUrl(
            element.dataset.coverSlot
          );

          break;
        }

        case "admin-save-cover-position":
        {
          await saveSiteCoverPosition(
            element.dataset.coverSlot
          );

          break;
        }

        case "admin-delete-cover":
        {
          await deleteSiteCover(
            element.dataset.coverSlot,
            "cover_images"
          );

          break;
        }

        case "admin-delete-collection-cover":
        {
          await deleteSiteCover(
            element.dataset.collectionSlug,
            "collection_covers"
          );

          break;
        }

        case "admin-save-collection":
        {
          await saveAdminCollection(
            element.dataset.collectionId
          );

          break;
        }

        case "admin-save-game":
        {
          await saveAdminGame(
            element.dataset.gameId
          );

          break;
        }

        default:
        {
          console.debug(
            "Acción no manejada:",
            action
          );
        }
      }
    }

    document.addEventListener(
      "click",
      async (
        event
      ) =>
      {
        const routeElement =
        event.target.closest(
          "[data-route]"
        );

        if (
          routeElement
        )
        {
          event.preventDefault();

          if (
            handleRouteElement(
              routeElement
            )
          )
          {
            return;
          }
        }

        const actionElement =
        event.target.closest(
          "[data-action]"
        );

        if (
          actionElement
        )
        {
          event.preventDefault();

          await handleAction(
            actionElement
          );
        }
      }
    );

    document.addEventListener(
      "change",
      async (
        event
      ) =>
      {
        const target =
        event.target;

        if (
          target.id === "languageSelect"
        )
        {
          state.language =
          target.value === "en"
          ?
          "en"
          :
          "es";

          saveLocalState();

          clearGameTimer();

          renderCurrentRoute();

          return;
        }

        if (
          target.id === "catalogSort"
        )
        {
          state.catalogSort =
          target.value
          ||
          "default";

          state.catalogPage =
          1;

          renderCurrentRoute();

          return;
        }

        if (
          target.id === "adminProductPageSize"
        )
        {
          state.admin.productPageSize =
          Math.max(
            10,
            Number(target.value) || 20
          );

          state.admin.productPage = 1;
          refreshAdminTab();
          return;
        }

        if (
          target.id === "giftOption"
        )
        {
          state.selectedGiftOption =
          target.value;

          state.giftDraft =
          [];

          renderCurrentRoute();

          return;
        }

        if (
          target.matches(
            'input[name="checkoutShipping"]'
          )
        )
        {
          toggleShippingFields();

          return;
        }

        if (
          target.matches(
            "[data-admin-seasonal-video-upload]"
          )
        )
        {
          const file =
          target.files?.[0];

          if (
            file
          )
          {
            try
            {
              adminMessage(
                "Subiendo video...",
                "ok"
              );

              await uploadSeasonalVideoFile(
                file
              );

              refreshAdminTab();

              adminMessage(
                "Video subido correctamente.",
                "ok"
              );
            }
            catch (
              error
            )
            {
              adminMessage(
                error.message,
                "error"
              );
            }
          }

          return;
        }

        if (
          target.matches(
            "[data-admin-cover-upload]"
          )
        )
        {
          const slot =
          target.dataset.adminCoverUpload;

          const file =
          target.files?.[0];

          if (file)
          {
            try
            {
              adminMessage(
                "Subiendo portada...",
                "ok"
              );

              await uploadSiteCoverFile(
                slot,
                file,
                "cover_images"
              );

              refreshAdminTab();

              adminMessage(
                "Portada actualizada correctamente.",
                "ok"
              );
            }
            catch (error)
            {
              adminMessage(
                error.message,
                "error"
              );
            }
          }

          return;
        }

        if (
          target.matches(
            "[data-admin-collection-cover-upload]"
          )
        )
        {
          const slug =
          target.dataset.adminCollectionCoverUpload;

          const file =
          target.files?.[0];

          if (file)
          {
            try
            {
              adminMessage(
                "Subiendo portada de colección...",
                "ok"
              );

              await uploadSiteCoverFile(
                slug,
                file,
                "collection_covers"
              );

              refreshAdminTab();

              adminMessage(
                "Portada de colección actualizada.",
                "ok"
              );
            }
            catch (error)
            {
              adminMessage(
                error.message,
                "error"
              );
            }
          }

          return;
        }

        if (
          target.matches(
            "[data-admin-upload]"
          )
        )
        {
          const productId =
          Number(
            target.dataset.adminUpload
          );

          const files =
          Array.from(
            target.files
            ||
            []
          );

          if (
            files.length
          )
          {
            try
            {
              adminMessage(
                state.language === "en"
                ?
                "Uploading photos..."
                :
                "Subiendo fotos...",
                "ok"
              );

              await uploadProductImages(
                productId,
                files
              );
            }
            catch (
              error
            )
            {
              adminMessage(
                error.message,
                "error"
              );
            }
          }

          return;
        }
      }
    );

    document.addEventListener(
      "input",
      (
        event
      ) =>
      {
        const target =
        event.target;

        if (
          target.id === "adminProductSearch"
        )
        {
          state.admin.productSearch =
          target.value;

          state.admin.productPage = 1;

          const selectionStart = target.selectionStart;
          const selectionEnd = target.selectionEnd;

          refreshAdminTab();

          const fresh =
          document.getElementById("adminProductSearch");

          if (fresh)
          {
            fresh.focus();
            try
            {
              fresh.setSelectionRange(selectionStart, selectionEnd);
            }
            catch (_) {}
          }

          return;
        }

        if (
          target.id === "catalogSearch"
        )
        {
          state.catalogSearch =
          target.value;

          state.catalogPage =
          1;

          const selectionStart =
          target.selectionStart;

          const selectionEnd =
          target.selectionEnd;

          const app =
          document.getElementById(
            "app"
          );

          if (
            app
          )
          {
            app.innerHTML =
            renderCatalogPage();
          }

          const fresh =
          document.getElementById(
            "catalogSearch"
          );

          if (
            fresh
          )
          {
            fresh.focus();

            try
            {
              fresh.setSelectionRange(
                selectionStart,
                selectionEnd
              );
            }
            catch (
              error
            )
            {
              void error;
            }
          }
        }
      }
    );

    document.addEventListener(
      "keydown",
      async (
        event
      ) =>
      {
        if (
          event.key === "Escape"
        )
        {
          closeMenu();

          closeCart();

          closeModal();

          return;
        }

        if (
          event.key === "Enter" &&
          event.target?.id === "globalSearchInput"
        )
        {
          event.preventDefault();

          submitGlobalSearch();

          return;
        }

        if (
          event.key === "Enter" &&
          event.target?.id === "advisorInput"
        )
        {
          event.preventDefault();

          await sendAdvisorMessage();
        }
      }
    );

    function validateCartAgainstStock()
    {
      let changed =
      false;

      const next =
      [];

      for (
        const line of
        state.cart
      )
      {
        if (
          line.kind !== "product"
        )
        {
          next.push(
            line
          );

          continue;
        }

        const product =
        getProductById(
          line.productId
          ??
          line.id
        );

        if (
          !product
        )
        {
          changed =
          true;

          continue;
        }

        const maxQty =
        Math.max(
          0,
          product.stock
        );

        if (
          maxQty <= 0
        )
        {
          changed =
          true;

          continue;
        }

        if (
          line.qty > maxQty
        )
        {
          line.qty =
          maxQty;

          changed =
          true;
        }

        next.push(
          line
        );
      }

      state.cart =
      next;

      if (
        changed
      )
      {
        saveLocalState();
      }
    }

    function exposeCompatibilityApi()
    {
      window.goHome =
      () =>
      setRoute(
        "home"
      );

      window.catalog =
      category =>
      {
        state.catalogFilter =
        category
        ||
        "Todos";

        setRoute(
          "catalog"
        );
      };

      window.showFavorites =
      () =>
      setRoute(
        "favorites"
      );

      window.openCart =
      openCart;

      window.closeCart =
      closeCart;

      window.openMenu =
      openMenu;

      window.closeMenu =
      closeMenu;

      window.closeModal =
      closeModal;

      window.checkout =
      openCheckout;

      window.addCart =
      addProductToCart;

      window.productDetail =
      id =>
      setRoute(
        "product",
        {
          id:
          id,
        }
      );

      window.showContact =
      () =>
      setRoute(
        "contact"
      );

      window.showAbout =
      () =>
      setRoute(
        "about"
      );

      window.showAdmin =
      () =>
      setRoute(
        "admin"
      );

      window.toggleFav =
      toggleFavorite;

      window.adminLogin =
      adminLogin;

      window.signOut =
      adminLogout;

      window.crearProducto =
      createProductFromAdmin;

      window.adminSave =
      saveAdminProduct;

      window.deleteProduct =
      deleteAdminProduct;

      window.uploadProductImages =
      uploadProductImages;
    }

    // Última defensa: si una URL pública falla porque el bucket sigue privado,
    // se firma únicamente ESA imagen visible y se reemplaza sin romper la tarjeta.
    document.addEventListener(
      "error",
      async event =>
      {
        const image = event.target;

        if (
          !(image instanceof HTMLImageElement) ||
          image.dataset.alpStorageRetry === "1"
        )
        {
          return;
        }

        const normalized = normalizeStoragePath(
          image.currentSrc || image.src || ""
        );

        if (
          normalized.kind !== "storage" ||
          !normalized.value
        )
        {
          return;
        }

        image.dataset.alpStorageRetry = "1";

        const signed = await createCachedSignedUrl(normalized.value);

        if (signed)
        {
          runtimeStorageMode = "private";
          writeStorageModeCache("private");
          image.src = signed;
        }
      },
      true
    );

    async function initialize()
    {
      applyLanguageToChrome();

      renderMobileMenu();

      renderFooter();

      updateHeaderCounts();

      exposeCompatibilityApi();

      await loadAllData();

      validateCartAgainstStock();

      updateHeaderCounts();

      window.setInterval(
        () =>
        {
          validateCartAgainstStock();
        },
        45000
      );

      supabaseClient.auth.onAuthStateChange(
        (
          event,
          session
        ) =>
        {
          state.admin.currentUser =
          session?.user
          ||
          null;

          if (
            state.route === "admin" &&
            (
              event === "SIGNED_IN" ||
              event === "SIGNED_OUT" ||
              event === "TOKEN_REFRESHED"
            )
          )
          {
            renderCurrentRoute();
          }
        }
      );
    }

    initialize();
